// Minimal Molang evaluator: enough for the expressions YSM models use in animations.
// Unknown variables evaluate to 0. Trigonometry follows Molang (degrees).

const D2R = Math.PI / 180;

const M = {
  sin: (x) => Math.sin(x * D2R),
  cos: (x) => Math.cos(x * D2R),
  asin: (x) => Math.asin(x) / D2R,
  acos: (x) => Math.acos(x) / D2R,
  atan: (x) => Math.atan(x) / D2R,
  atan2: (y, x) => Math.atan2(y, x) / D2R,
  abs: Math.abs,
  sqrt: Math.sqrt,
  pow: Math.pow,
  exp: Math.exp,
  ln: Math.log,
  floor: Math.floor,
  ceil: Math.ceil,
  round: Math.round,
  trunc: Math.trunc,
  min: Math.min,
  max: Math.max,
  mod: (a, b) => a % b,
  clamp: (v, a, b) => Math.min(Math.max(v, a), b),
  lerp: (a, b, t) => a + (b - a) * t,
  random: (a, b) => a + Math.random() * (b - a),
  pi: Math.PI,
};

const SAFE = /^[\w\s.+\-*/%()?:<>=!&|,]*$/;

export function compileMolang(expr) {
  if (typeof expr === 'number') return () => expr;
  if (typeof expr === 'boolean') return () => (expr ? 1 : 0);
  const src = String(expr ?? '').trim();
  if (src === '') return () => 0;
  const num = Number(src);
  if (!Number.isNaN(num)) return () => num;
  if (!SAFE.test(src)) return () => 0;

  const js = src
    .toLowerCase()
    .replace(/\bmath\.pi\b/g, 'M.pi')
    .replace(/\bmath\.(\w+)/g, 'M.$1')
    .replace(/\b(query|q|ysm|variable|v|temp|t|context|c)\.(\w+)/g, (_, ns, name) => {
      const n = { q: 'query', v: 'variable', t: 'temp', c: 'context' }[ns] || ns;
      return `(ctx.${n}_${name}||0)`;
    })
    .replace(/(^|[^=!<>])=(?!=)/g, '$1==');

  try {
    const fn = new Function('ctx', 'M', `return (${js});`);
    return (ctx) => {
      try {
        const v = Number(fn(ctx, M));
        return Number.isFinite(v) ? v : 0;
      } catch {
        return 0;
      }
    };
  } catch {
    return () => 0;
  }
}

import * as THREE from '../../node_modules/three/build/three.module.js';

// Converts Bedrock (YSM / Blockbench) geometry into a three.js bone hierarchy.
// Follows Blockbench's bedrock import conventions: X is mirrored, rotations use
// ZYX order with X and Y angles negated. The resulting model faces -Z.

const D2R = Math.PI / 180;
const FACE_SHADE = { north: 1, south: 1, east: 0.82, west: 0.82, up: 1, down: 0.62 };

export function bedrockRotation(r) {
  return new THREE.Euler(-(r?.[0] || 0) * D2R, -(r?.[1] || 0) * D2R, (r?.[2] || 0) * D2R, 'ZYX');
}

function bbPoint(p) {
  return new THREE.Vector3(-(p?.[0] || 0), p?.[1] || 0, p?.[2] || 0);
}

// Corners as seen from outside the face: top-left, top-right, bottom-left, bottom-right.
function faceCorners(face, a, b) {
  const [x0, y0, z0] = a;
  const [x1, y1, z1] = b;
  switch (face) {
    case 'north': return [[x1, y1, z0], [x0, y1, z0], [x1, y0, z0], [x0, y0, z0]];
    case 'south': return [[x0, y1, z1], [x1, y1, z1], [x0, y0, z1], [x1, y0, z1]];
    case 'east': return [[x1, y1, z1], [x1, y1, z0], [x1, y0, z1], [x1, y0, z0]];
    case 'west': return [[x0, y1, z0], [x0, y1, z1], [x0, y0, z0], [x0, y0, z1]];
    case 'up': return [[x0, y1, z0], [x1, y1, z0], [x0, y1, z1], [x1, y1, z1]];
    case 'down': return [[x0, y0, z1], [x1, y0, z1], [x0, y0, z0], [x1, y0, z0]];
  }
  return null;
}

// Box UV layout (used when a cube's "uv" is a [u, v] array).
function boxUV(uv, size, mirror) {
  const [u, v] = uv;
  const [w, h, d] = size.map((s) => Math.floor(s));
  const faces = {
    east: [u, v + d, d, h],
    north: [u + d, v + d, w, h],
    west: [u + d + w, v + d, d, h],
    south: [u + d + w + d, v + d, w, h],
    up: [u + d + w, v + d, -w, -d],
    down: [u + d + w + w, v, -w, d],
  };
  const out = {};
  for (const [k, [fu, fv, fw, fh]] of Object.entries(faces)) {
    out[k] = mirror ? { uv: [fu + fw, fv], uv_size: [-fw, fh] } : { uv: [fu, fv], uv_size: [fw, fh] };
  }
  if (mirror) [out.east, out.west] = [out.west, out.east];
  return out;
}

function buildBoneGeometry(bone, bonePivot, texW, texH) {
  const pos = [];
  const uvs = [];
  const col = [];
  const idx = [];

  for (const cube of bone.cubes || []) {
    const inflate = cube.inflate || 0;
    const o = cube.origin || [0, 0, 0];
    const s = cube.size || [0, 0, 0];
    const from = [-(o[0] + s[0]) - inflate, o[1] - inflate, o[2] - inflate];
    const to = [-o[0] + inflate, o[1] + s[1] + inflate, o[2] + s[2] + inflate];

    let xform = null;
    if (cube.rotation) {
      const piv = bbPoint(cube.pivot);
      const m = new THREE.Matrix4().makeRotationFromEuler(bedrockRotation(cube.rotation));
      xform = new THREE.Matrix4()
        .makeTranslation(piv.x, piv.y, piv.z)
        .multiply(m)
        .multiply(new THREE.Matrix4().makeTranslation(-piv.x, -piv.y, -piv.z));
    }

    const faces = Array.isArray(cube.uv) ? boxUV(cube.uv, s, cube.mirror) : cube.uv || {};
    for (const [face, def] of Object.entries(faces)) {
      if (!def || !def.uv) continue;
      const corners = faceCorners(face, from, to);
      if (!corners) continue;
      const size = def.uv_size || [0, 0];
      let u1, v1, u2, v2;
      if (face === 'up' || face === 'down') {
        u1 = def.uv[0] + size[0]; v1 = def.uv[1] + size[1];
        u2 = def.uv[0]; v2 = def.uv[1];
      } else {
        u1 = def.uv[0]; v1 = def.uv[1];
        u2 = def.uv[0] + size[0]; v2 = def.uv[1] + size[1];
      }
      const faceUV = [[u1, v1], [u2, v1], [u1, v2], [u2, v2]];
      const shade = FACE_SHADE[face];
      const base = pos.length / 3;
      for (let i = 0; i < 4; i++) {
        const v = new THREE.Vector3(...corners[i]);
        if (xform) v.applyMatrix4(xform);
        v.sub(bonePivot);
        pos.push(v.x, v.y, v.z);
        uvs.push(faceUV[i][0] / texW, 1 - faceUV[i][1] / texH);
        col.push(shade, shade, shade);
      }
      idx.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
    }
  }

  if (!pos.length) return null;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  return g;
}

export function buildModel(geoJson, texture) {
  const geo = geoJson['minecraft:geometry'][0];
  const texW = geo.description?.texture_width || 64;
  const texH = geo.description?.texture_height || 64;

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    vertexColors: true,
    alphaTest: 0.1,
    side: THREE.DoubleSide,
  });

  const root = new THREE.Group();
  const bones = new Map();

  for (const b of geo.bones) {
    const group = new THREE.Group();
    group.name = b.name;
    const pivot = bbPoint(b.pivot);
    group.userData.pivot = pivot;
    group.rotation.copy(bedrockRotation(b.rotation));
    const g = buildBoneGeometry(b, pivot, texW, texH);
    if (g) group.add(new THREE.Mesh(g, material));
    bones.set(b.name, group);
  }

  for (const b of geo.bones) {
    const group = bones.get(b.name);
    const parent = b.parent ? bones.get(b.parent) : null;
    const parentPivot = parent ? parent.userData.pivot : new THREE.Vector3();
    group.position.copy(group.userData.pivot).sub(parentPivot);
    (parent || root).add(group);
    group.userData.restPos = group.position.clone();
    group.userData.restRot = group.rotation.clone();
  }

  root.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(root);
  return { root, bones, box, material };
}

import { compileMolang } from './molang.js';

const D2R = Math.PI / 180;

function compileVec(v, isScale) {
  if (Array.isArray(v)) {
    const fns = [0, 1, 2].map((i) => compileMolang(v[i] ?? 0));
    return (ctx) => [fns[0](ctx), fns[1](ctx), fns[2](ctx)];
  }
  const f = compileMolang(v ?? (isScale ? 1 : 0));
  return (ctx) => {
    const s = f(ctx);
    return [s, s, s];
  };
}

function isKeyframeMap(v) {
  return v && typeof v === 'object' && !Array.isArray(v) && Object.keys(v).some((k) => !Number.isNaN(parseFloat(k)));
}

function compileChannel(spec, isScale) {
  if (spec == null) return null;
  if (!isKeyframeMap(spec)) {
    if (spec && typeof spec === 'object' && !Array.isArray(spec)) {
      const v = compileVec(spec.post ?? spec.pre, isScale);
      return { length: 0, sample: v };
    }
    return { length: 0, sample: compileVec(spec, isScale) };
  }

  const keys = Object.entries(spec)
    .map(([t, val]) => {
      let pre, post, lerp = 'linear';
      if (val && typeof val === 'object' && !Array.isArray(val)) {
        post = val.post ?? val.pre;
        pre = val.pre ?? val.post;
        lerp = val.lerp_mode || 'linear';
      } else {
        pre = post = val;
      }
      return { t: parseFloat(t), pre: compileVec(pre, isScale), post: compileVec(post, isScale), lerp };
    })
    .filter((k) => !Number.isNaN(k.t))
    .sort((a, b) => a.t - b.t);

  const length = keys.length ? keys[keys.length - 1].t : 0;

  const sample = (ctx, time) => {
    if (keys.length === 1 || time <= keys[0].t) return keys[0].pre(ctx);
    const last = keys[keys.length - 1];
    if (time >= last.t) return last.post(ctx);
    let i = 0;
    while (i < keys.length - 1 && keys[i + 1].t <= time) i++;
    const k0 = keys[i];
    const k1 = keys[i + 1];
    const a = (time - k0.t) / (k1.t - k0.t || 1);
    const p1 = k0.post(ctx);
    const p2 = k1.pre(ctx);
    if (k0.lerp === 'catmullrom' || k1.lerp === 'catmullrom') {
      const p0 = (keys[i - 1] || k0).post(ctx);
      const p3 = (keys[i + 2] || k1).pre(ctx);
      return [0, 1, 2].map((j) => catmull(p0[j], p1[j], p2[j], p3[j], a));
    }
    return [0, 1, 2].map((j) => p1[j] + (p2[j] - p1[j]) * a);
  };

  return { length, sample };
}

function catmull(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return 0.5 * (2 * p1 + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
}

export class AnimClip {
  constructor(name, json) {
    this.name = name;
    this.loop = json.loop === true || json.loop === 'true' ? 'loop' : json.loop === 'hold_on_last_frame' ? 'hold' : 'once';
    this.bones = {};
    let maxKey = 0;
    for (const [bone, chans] of Object.entries(json.bones || {})) {
      const c = {
        rotation: compileChannel(chans.rotation, false),
        position: compileChannel(chans.position, false),
        scale: compileChannel(chans.scale, true),
      };
      for (const ch of Object.values(c)) if (ch) maxKey = Math.max(maxKey, ch.length);
      this.bones[bone] = c;
    }
    this.length = Number(json.animation_length) || maxKey;
  }

  localTime(t) {
    if (this.length <= 0) return 0;
    if (this.loop === 'loop') return t % this.length;
    return Math.min(t, this.length);
  }

  finished(t) {
    return this.loop !== 'loop' && t >= this.length;
  }
}

export function loadClips(animFiles) {
  const clips = new Map();
  for (const file of animFiles) {
    for (const [name, json] of Object.entries(file.animations || {})) {
      clips.set(name, new AnimClip(name, json));
    }
  }
  return clips;
}

// Drives a bone hierarchy with one main clip at a time, crossfading between clips.
export class Animator {
  constructor(bones, clips) {
    this.bones = bones;
    this.clips = clips;
    this.ctx = {};
    this.current = null;
    this.time = 0;
    this.fadeFrom = null;
    this.fade = 1;
    this.fadeDuration = 0.18;
    this.pose = new Map();
  }

  has(name) {
    return this.clips.has(name);
  }

  play(name, { restart = false, fade = 0.18 } = {}) {
    const clip = this.clips.get(name);
    if (!clip) return;
    if (this.current === clip && !restart) return;
    this.fadeFrom = this.pose.size ? new Map([...this.pose].map(([k, v]) => [k, v.map((a) => a.slice())])) : null;
    this.fade = fade > 0 && this.fadeFrom ? 0 : 1;
    this.fadeDuration = fade;
    this.current = clip;
    this.time = 0;
  }

  get finished() {
    return this.current ? this.current.finished(this.time) : true;
  }

  samplePose(clip, time) {
    const pose = new Map();
    const lt = clip.localTime(time);
    for (const [name, ch] of Object.entries(clip.bones)) {
      if (!this.bones.has(name)) continue;
      const rot = ch.rotation ? ch.rotation.sample(this.ctx, lt) : [0, 0, 0];
      const pos = ch.position ? ch.position.sample(this.ctx, lt) : [0, 0, 0];
      const scl = ch.scale ? ch.scale.sample(this.ctx, lt) : [1, 1, 1];
      pose.set(name, [rot, pos, scl]);
    }
    return pose;
  }

  update(dt) {
    if (!this.current) return;
    this.time += dt;
    if (this.fade < 1) this.fade = Math.min(1, this.fade + dt / this.fadeDuration);

    const target = this.samplePose(this.current, this.time);
    const pose = new Map();
    const ident = [[0, 0, 0], [0, 0, 0], [1, 1, 1]];
    const names = new Set([...target.keys(), ...(this.fade < 1 && this.fadeFrom ? this.fadeFrom.keys() : [])]);
    const f = this.fade;
    for (const name of names) {
      const b = target.get(name) || ident;
      if (f >= 1 || !this.fadeFrom) {
        pose.set(name, b);
        continue;
      }
      const a = this.fadeFrom.get(name) || ident;
      pose.set(name, [0, 1, 2].map((c) => [0, 1, 2].map((j) => a[c][j] + (b[c][j] - a[c][j]) * f)));
    }
    this.pose = pose;

    for (const [name, bone] of this.bones) {
      const p = pose.get(name) || ident;
      const rr = bone.userData.restRot;
      const rp = bone.userData.restPos;
      bone.rotation.set(rr.x - p[0][0] * D2R, rr.y - p[0][1] * D2R, rr.z + p[0][2] * D2R, 'ZYX');
      bone.position.set(rp.x - p[1][0], rp.y + p[1][1], rp.z + p[1][2]);
      bone.scale.set(p[2][0], p[2][1], p[2][2]);
    }
  }
}

const koffi = require('koffi');

const user32 = koffi.load('user32.dll');
const dwmapi = koffi.load('dwmapi.dll');

const GetTopWindow = user32.func('intptr_t __stdcall GetTopWindow(intptr_t hWnd)');
const GetWindow = user32.func('intptr_t __stdcall GetWindow(intptr_t hWnd, uint32_t uCmd)');
const IsWindowVisible = user32.func('bool __stdcall IsWindowVisible(intptr_t hWnd)');
const IsIconic = user32.func('bool __stdcall IsIconic(intptr_t hWnd)');
const IsZoomed = user32.func('bool __stdcall IsZoomed(intptr_t hWnd)');
const GetWindowLongW = user32.func('int32_t __stdcall GetWindowLongW(intptr_t hWnd, int nIndex)');
const GetWindowTextLengthW = user32.func('int __stdcall GetWindowTextLengthW(intptr_t hWnd)');
const GetClassNameW = user32.func('int __stdcall GetClassNameW(intptr_t hWnd, void *buf, int maxCount)');
const GetWindowRect = user32.func('bool __stdcall GetWindowRect(intptr_t hWnd, void *rect)');
const GetWindowThreadProcessId = user32.func('uint32_t __stdcall GetWindowThreadProcessId(intptr_t hWnd, void *pid)');
const DwmGetWindowAttribute = dwmapi.func('int32_t __stdcall DwmGetWindowAttribute(intptr_t hWnd, uint32_t attr, void *pv, uint32_t cb)');

const GW_HWNDNEXT = 2;
const GWL_STYLE = -16;
const GWL_EXSTYLE = -20;
const WS_CHILD = 0x40000000;
const WS_EX_TOOLWINDOW = 0x00000080;
const WS_EX_TRANSPARENT = 0x00000020;
const WS_EX_NOACTIVATE = 0x08000000;
const WS_EX_APPWINDOW = 0x00040000;
const DWMWA_EXTENDED_FRAME_BOUNDS = 9;
const DWMWA_CLOAKED = 14;

const IGNORED_CLASSES = new Set([
  'Progman',
  'WorkerW',
  'Shell_TrayWnd',
  'Shell_SecondaryTrayWnd',
  'NotifyIconOverflowWindow',
  'Windows.UI.Core.CoreWindow',
  'ForegroundStaging',
  'MultitaskingViewFrame',
  'XamlExplorerHostIslandWindow',
  'TopLevelWindowForOverflowXamlIsland',
]);

const rectBuf = Buffer.alloc(16);
const intBuf = Buffer.alloc(4);
const classBuf = Buffer.alloc(512);

function readRect(buf) {
  return { left: buf.readInt32LE(0), top: buf.readInt32LE(4), right: buf.readInt32LE(8), bottom: buf.readInt32LE(12) };
}

function className(hwnd) {
  const n = GetClassNameW(hwnd, classBuf, 256);
  return n > 0 ? classBuf.toString('utf16le', 0, n * 2) : '';
}

function frameRect(hwnd) {
  if (DwmGetWindowAttribute(hwnd, DWMWA_EXTENDED_FRAME_BOUNDS, rectBuf, 16) === 0) return readRect(rectBuf);
  if (GetWindowRect(hwnd, rectBuf)) return readRect(rectBuf);
  return null;
}

function isCloaked(hwnd) {
  intBuf.writeUInt32LE(0, 0);
  if (DwmGetWindowAttribute(hwnd, DWMWA_CLOAKED, intBuf, 4) !== 0) return false;
  return intBuf.readUInt32LE(0) !== 0;
}

function processId(hwnd) {
  intBuf.writeUInt32LE(0, 0);
  GetWindowThreadProcessId(hwnd, intBuf);
  return intBuf.readUInt32LE(0);
}

// Visible top-level app windows, ordered from topmost to bottom-most.
// Rects are in physical screen pixels.
function listWindows(ignorePid) {
  const out = [];
  let hwnd = GetTopWindow(0);
  let guard = 0;
  while (hwnd && guard++ < 2000) {
    const h = hwnd;
    hwnd = GetWindow(h, GW_HWNDNEXT);

    if (!IsWindowVisible(h) || IsIconic(h)) continue;
    const style = GetWindowLongW(h, GWL_STYLE);
    if (style & WS_CHILD) continue;
    const ex = GetWindowLongW(h, GWL_EXSTYLE);
    if (ex & WS_EX_TRANSPARENT) continue;
    if ((ex & WS_EX_TOOLWINDOW) && !(ex & WS_EX_APPWINDOW)) continue;
    if ((ex & WS_EX_NOACTIVATE) && !(ex & WS_EX_APPWINDOW)) continue;
    if (GetWindowTextLengthW(h) === 0) continue;
    if (IGNORED_CLASSES.has(className(h))) continue;
    if (isCloaked(h)) continue;
    if (ignorePid && processId(h) === ignorePid) continue;

    const r = frameRect(h);
    if (!r || r.right - r.left < 60 || r.bottom - r.top < 40) continue;
    out.push({ id: String(h), rect: r, maximized: IsZoomed(h) });
  }
  return out;
}

module.exports = { listWindows };

const { app, BrowserWindow, screen, ipcMain, Tray, Menu, nativeImage } = require('electron');
const path = require('path');
const fs = require('fs');
const { listWindows } = require('./win32');

const ROOT = path.join(__dirname, '..');
const PREVIEW = process.argv.includes('--preview');

let win = null;
let tray = null;
let display = null;
let pollTimer = null;

function loadConfig() {
  const defaults = {
    modelDir: 'DaL_Kurumi',
    display: 'primary',
    petHeight: 110,
    walkSpeed: 0.5,
    runSpeed: 1.4,
    climbSpeed: 0.4,
    gravity: 16,
    climbChance: 0.6,
    debug: false,
  };
  try {
    return { ...defaults, ...JSON.parse(fs.readFileSync(path.join(ROOT, 'config.json'), 'utf8')) };
  } catch {
    return defaults;
  }
}

const config = loadConfig();

function pickDisplay() {
  const all = screen.getAllDisplays();
  if (typeof config.display === 'number' && all[config.display]) return all[config.display];
  return screen.getPrimaryDisplay();
}

function loadModelFiles() {
  const dir = path.resolve(ROOT, config.modelDir);
  const readJson = (f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
  const files = fs.readdirSync(dir);
  const geoFile = files.includes('main.json') ? 'main.json' : files.find((f) => f.endsWith('.json') && !f.includes('animation'));
  const animFiles = ['main.animation.json', 'extra.animation.json', ...files.filter((f) => f.endsWith('.animation.json'))]
    .filter((f, i, a) => files.includes(f) && a.indexOf(f) === i && !f.startsWith('arm') && !f.startsWith('tac'));
  const texFile = files.includes('texture.png') ? 'texture.png' : files.find((f) => f.endsWith('.png'));
  return {
    geometry: readJson(geoFile),
    animations: animFiles.map(readJson),
    texture: 'data:image/png;base64,' + fs.readFileSync(path.join(dir, texFile)).toString('base64'),
  };
}

function pollWorld() {
  if (!win || win.isDestroyed()) return;
  const wa = display.workArea;
  const windows = [];
  for (const w of listWindows(process.pid)) {
    const r = w.rect;
    const dip = screen.screenToDipRect(null, { x: r.left, y: r.top, width: r.right - r.left, height: r.bottom - r.top });
    const x = dip.x - wa.x;
    const y = dip.y - wa.y;
    if (x > wa.width || y > wa.height || x + dip.width < 0 || y + dip.height < 0) continue;
    windows.push({ id: w.id, x, y, w: dip.width, h: dip.height, maximized: w.maximized });
  }
  win.webContents.send('world', { width: wa.width, height: wa.height, windows });
}

function fitToDisplay() {
