    },
  });

  if (!PREVIEW) {
    win.setAlwaysOnTop(true, 'screen-saver');
    win.setIgnoreMouseEvents(true);
    win.setVisibleOnAllWorkspaces(true);
  }

  win.loadFile(path.join(__dirname, 'renderer', 'index.html'), { query: PREVIEW ? { preview: '1' } : {} });

