import * as THREE from '../../node_modules/three/build/three.module.js';
import { buildModel } from './model.js';
import { loadClips, Animator } from './animation.js';

// Model faces -Z; the camera looks at it from +Z.
const YAW = { front: Math.PI, back: 0, right: -Math.PI / 2, left: Math.PI / 2 };

function loadTexture(dataUrl) {
  return new Promise((resolve, reject) => {
    new THREE.TextureLoader().load(
      dataUrl,
      (t) => {
        t.magFilter = THREE.NearestFilter;
        t.minFilter = THREE.NearestFilter;
        t.generateMipmaps = false;
        t.colorSpace = THREE.SRGBColorSpace;
        t.flipY = true;
        resolve(t);
      },
      undefined,
      reject,
    );
  });
}

export class PetView {
  static async create(files, petHeight, canvas) {
    const texture = await loadTexture(files.texture);
    const model = buildModel(files.geometry, texture);
    const clips = loadClips(files.animations);
    return new PetView(model, clips, petHeight, canvas);
  }

  constructor(model, clips, petHeight, canvas) {
    this.model = model;
    this.animator = new Animator(model.bones, clips);
    this.petHeight = petHeight;
    this.modelHeight = Math.max(1, model.box.max.y - Math.min(0, model.box.min.y));
    this.ppu = petHeight / this.modelHeight;

    this.width = Math.round(petHeight * 2.4);
    this.height = Math.round(petHeight * 1.8);
    this.feetX = this.width / 2;
    this.feetY = Math.round(this.height - petHeight * 0.3);

    this.canvas = canvas;
    canvas.width = Math.round(this.width * devicePixelRatio);
    canvas.height = Math.round(this.height * devicePixelRatio);
    canvas.style.width = this.width + 'px';
    canvas.style.height = this.height + 'px';

    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, preserveDrawingBuffer: true });
    this.renderer.setPixelRatio(devicePixelRatio);
    this.renderer.setSize(this.width, this.height, false);
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;

    this.scene = new THREE.Scene();
    this.yawGroup = new THREE.Group();
    this.yawGroup.add(model.root);
    this.scene.add(this.yawGroup);

    const u = 1 / this.ppu;
    this.camera = new THREE.OrthographicCamera(
      -this.feetX * u,
      (this.width - this.feetX) * u,
      this.feetY * u,
      -(this.height - this.feetY) * u,
      0.1,
      1000,
    );
    this.camera.position.set(0, 0, 200);
    this.camera.lookAt(0, 0, 0);

    this.facing = 'front';
    this.setFacing('front');
  }

  setFacing(facing) {
    this.facing = facing;
    this.yawGroup.rotation.set(0, YAW[facing] ?? 0, 0);
  }

  play(name, opts) {
    this.animator.play(name, opts);
  }

  update(dt) {
    this.animator.update(dt);
    this.renderer.render(this.scene, this.camera);
  }
}

import { PetView } from './view.js';

// Renders every animation at a few timestamps and facings into PNG sheets under /preview.
export async function runPreview(files, config) {
  const canvas = document.getElementById('pet');
  const view = await PetView.create(files, config.petHeight, canvas);
  const names = config.previewAnims || [...view.animator.clips.keys()].filter((n) => !/parallel/.test(n));
  const facings = ['front', 'right', 'left', 'back'];
  const times = 4;

  const sheet = document.createElement('canvas');
  sheet.width = view.width * times;
  sheet.height = view.height * facings.length;
  const g = sheet.getContext('2d');

  for (const name of names) {
    const clip = view.animator.clips.get(name);
    g.fillStyle = '#6a8caf';
    g.fillRect(0, 0, sheet.width, sheet.height);
    facings.forEach((facing, row) => {
      view.setFacing(facing);
      for (let i = 0; i < times; i++) {
        view.play(name, { restart: true, fade: 0 });
        view.update((clip.length || 1) * (i / times) + 0.0001);
        g.drawImage(canvas, i * view.width, row * view.height, view.width, view.height);
        g.strokeStyle = 'rgba(255,255,255,0.25)';
        g.beginPath();
        g.moveTo(i * view.width, row * view.height + view.feetY + 0.5);
        g.lineTo((i + 1) * view.width, row * view.height + view.feetY + 0.5);
        g.stroke();
      }
    });
    g.fillStyle = '#fff';
    g.font = '14px sans-serif';
    g.fillText(name, 6, 16);
    await window.petAPI.savePreview(name.replace(/[^\w]+/g, '_'), sheet.toDataURL('image/png'));
  }
  window.petAPI.previewDone();
}

