// Walkable geometry derived from the desktop's windows.
// Surfaces: visible parts of window top edges + the floor (taskbar top).
// Walls: visible parts of window left/right edges.
// Coordinates are overlay-local DIPs; windows arrive ordered topmost first.

function subtract(intervals, a, b) {
  const out = [];
  for (const [s, e] of intervals) {
    if (b <= s || a >= e) {
      out.push([s, e]);
      continue;
    }
    if (a > s) out.push([s, a]);
    if (b < e) out.push([b, e]);
  }
  return out;
}

export class World {
  constructor(petHeight) {
    this.petHeight = petHeight;
    this.width = 0;
    this.height = 0;
    this.windows = new Map();
    this.surfaces = [];
    this.walls = [];
    this.ready = false;
  }

  // Returns per-window movement since the previous update: Map<id, {dx, dy}>.
  update(data) {
    const moved = new Map();
    const next = new Map();
    for (const w of data.windows) {
      const r = { id: w.id, x: w.x, y: w.y, w: w.w, h: w.h, right: w.x + w.w, bottom: w.y + w.h, maximized: w.maximized };
      const prev = this.windows.get(w.id);
      if (prev && (prev.x !== r.x || prev.y !== r.y)) moved.set(w.id, { dx: r.x - prev.x, dy: r.y - prev.y });
      next.set(w.id, r);
    }
    this.windows = next;
    this.width = data.width;
    this.height = data.height;
    this.rebuild([...next.values()]);
    this.ready = true;
    return moved;
  }

  rebuild(order) {
    const W = this.width;
    const H = this.height;
    const minTop = this.petHeight * 1.05;
    const surfaces = [{ id: 'floor', y: H, x1: 0, x2: W }];
    const walls = [];

    order.forEach((r, i) => {
      const above = order.slice(0, i);

      if (!r.maximized && r.y >= minTop && r.y < H - 4) {
        let segs = [[Math.max(0, r.x), Math.min(W, r.right)]];
        for (const o of above) {
          if (o.y < r.y && o.bottom > r.y - 2) segs = subtract(segs, o.x, o.right);
        }
        for (const [x1, x2] of segs) if (x2 - x1 >= 24) surfaces.push({ id: r.id, y: r.y, x1, x2 });
      }

      if (r.maximized) return;
      for (const side of ['left', 'right']) {
        const x = side === 'left' ? r.x : r.right;
        if (x <= 0 || x >= W) continue;
        let segs = [[Math.max(0, r.y), Math.min(H, r.bottom)]];
        for (const o of above) {
          if (o.x < x + 1 && o.right > x - 1) segs = subtract(segs, o.y, o.bottom);
        }
        for (const [y1, y2] of segs) if (y2 - y1 >= 8) walls.push({ id: r.id, side, x, y1, y2, top: r.y });
      }
    });

    this.surfaces = surfaces;
    this.walls = walls;
  }

  window(id) {
    return this.windows.get(id);
  }

  // Surface segment belonging to `id` that contains x (with tolerance).
  surfaceAt(id, x, tol = 1) {
    for (const s of this.surfaces) {
      if (s.id === id && x >= s.x1 - tol && x <= s.x2 + tol) return s;
    }
    return null;
  }

  // First surface crossed when moving down from y0 to y1 at x.
  landing(x, y0, y1, exclude) {
    let best = null;
    for (const s of this.surfaces) {
      if (s.id === exclude) continue;
      if (x < s.x1 || x > s.x2) continue;
      if (s.y >= y0 - 0.5 && s.y <= y1 + 0.5 && (!best || s.y < best.y)) best = s;
    }
    return best;
  }

  wallAt(id, side, y, tol = 2) {
    for (const w of this.walls) {
      if (w.id === id && w.side === side && y >= w.y1 - tol && y <= w.y2 + tol) return w;
    }
    return null;
  }

  // Walls crossed while walking horizontally from x0 to x1 at height y.
  wallsCrossed(x0, x1, y, dir) {
    const side = dir > 0 ? 'left' : 'right';
    const lo = Math.min(x0, x1);
    const hi = Math.max(x0, x1);
    return this.walls.filter((w) => w.side === side && w.x >= lo && w.x <= hi && w.y1 < y - 2);
  }
}

import { PetView } from './view.js';
import { World } from './world.js';

const rand = (a, b) => a + Math.random() * (b - a);
const chance = (p) => Math.random() < p;
const clamp = (v, a, b) => Math.min(Math.max(v, a), b);

function pickWeighted(weights) {
  const entries = Object.entries(weights).filter(([, w]) => w > 0);
  let r = Math.random() * entries.reduce((s, [, w]) => s + w, 0);
  for (const [k, w] of entries) {
    if ((r -= w) <= 0) return k;
  }
  return entries[0][0];
}

class Pet {
  constructor(view, world, cfg) {
    this.view = view;
    this.world = world;
    this.cfg = cfg;
    const P = (this.P = cfg.petHeight);
    this.walkSpeed = cfg.walkSpeed * P;
    this.runSpeed = cfg.runSpeed * P;
    this.climbSpeed = cfg.climbSpeed * P;
    this.gravity = cfg.gravity * P;
    this.jumpReach = cfg.jumpReach * P;
    this.climbInset = P * 0.14;
    this.edgeMargin = P * 0.08;
    this.emotes = (cfg.emotes || []).filter((e) => view.animator.has(e));

    this.x = null;
    this.y = null;
    this.dir = 1;
    this.mode = 'air';
    this.surfaceId = null;
    this.wall = null;
    this.vx = 0;
    this.vy = 0;
    this.action = null;
    this.timer = 0;
    this.awake = 0;
    this.jump = null;
  }

  anim(name, { pose = 'stand', facing = 'front', speed = 1, restart = false } = {}) {
    const poseChanged = this.view.pose !== pose;
    if (poseChanged) this.view.setPose(pose);
    this.view.setFacing(facing);
    this.view.play(name, { restart, fade: poseChanged ? 0 : 0.18, speed });
  }

  side() {
    return this.dir > 0 ? 'right' : 'left';
  }

  spawn() {
    const W = this.world.width;
    this.x = rand(this.P, W - this.P);
    this.y = this.P * 0.2;
    this.fall(0, 0);
  }

  // ---------- world sync ----------

  onWorldUpdate(moved) {
    if (this.x === null) return this.spawn();
    if (this.mode === 'ground') {
      const m = moved.get(this.surfaceId);
      if (m) {
        this.x += m.dx;
        this.y += m.dy;
      }
      this.validateGround();
    } else if (this.mode === 'wall') {
      const m = moved.get(this.wall.id);
      if (m) {
        this.x += m.dx;
        this.y += m.dy;
      }
      this.validateWall();
    }
  }

  validateGround() {
    const s = this.world.surfaceAt(this.surfaceId, this.x, 2);
    if (!s) {
      this.fall(0, 0);
      return null;
    }
    this.y = s.y;
    this.x = clamp(this.x, Math.max(s.x1, this.P * 0.15), Math.min(s.x2, this.world.width - this.P * 0.15));
    return s;
  }

  validateWall() {
    const w = this.world.wallAt(this.wall.id, this.wall.side, this.y);
    if (!w) {
      this.fall(0, 0);
      return null;
    }
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    return w;
  }

  // ---------- ground ----------

  land(s) {
    this.mode = 'ground';
    this.surfaceId = s.id;
    this.y = s.y;
    this.vx = this.vy = 0;
    this.action = 'land';
    this.timer = 0.35;
    this.anim('idle');
  }

  startGround(kind) {
    this.action = kind;
    const f = this.side();
    switch (kind) {
      case 'walk':
        if (chance(0.35)) this.dir = -this.dir;
        this.timer = rand(3, 9);
        this.anim('walk', { facing: this.side() });
        break;
      case 'run':
        if (chance(0.35)) this.dir = -this.dir;
        this.timer = rand(1.5, 3.5);
        this.anim('run', { facing: this.side() });
        break;
      case 'sit':
        this.timer = rand(6, 15);
        this.anim('sit', { facing: f });
        break;
      case 'sleep':
        this.timer = rand(20, 45);
        this.awake = 0;
        this.anim('sleep', { pose: 'lie', facing: f });
        break;
      case 'emote': {
        const name = this.emotes[Math.floor(Math.random() * this.emotes.length)];
        const clip = this.view.animator.clips.get(name);
        this.timer = clip.loop === 'loop' ? clip.length * Math.max(1, Math.ceil(2.5 / clip.length)) : clip.length + 0.8;
        this.anim(name, { restart: true });
        break;
      }
      default:
        this.action = 'idle';
        this.timer = rand(2, 5);
        this.anim('idle');
    }
  }

  chooseNext() {
    this.startGround(
      pickWeighted({
        walk: 45,
        idle: 18,
        run: 7,
        sit: 10,
        emote: this.emotes.length ? 12 : 0,
        sleep: this.awake > 90 ? 6 : 0,
      }),
    );
  }

  updateGround(dt) {
    const s = this.validateGround();
    if (!s) return;

    if (this.action === 'walk' || this.action === 'run') {
      const speed = this.action === 'run' ? this.runSpeed : this.walkSpeed;
      const nx = this.x + this.dir * speed * dt;
      if (this.tryClimbWall(this.x, nx)) return;

      const lo = Math.max(s.x1 + this.edgeMargin, this.P * 0.2);
      const hi = Math.min(s.x2 - this.edgeMargin, this.world.width - this.P * 0.2);
      if ((this.dir > 0 && nx >= hi) || (this.dir < 0 && nx <= lo)) {
        this.x = clamp(nx, lo, hi);
        this.onEdge(s);
        return;
      }
      this.x = nx;
    }

    this.timer -= dt;
    if (this.timer <= 0) this.chooseNext();
  }

  onEdge(s) {
    const win = s.id === 'floor' ? null : this.world.window(s.id);
    const realEdge = win && (this.dir > 0 ? Math.abs(s.x2 - win.right) < 2 : Math.abs(s.x1 - win.x) < 2);
    if (realEdge) {
      const wall = this.world.wallAt(s.id, this.side(), this.y + 4, 0);
      const r = Math.random();
      if (wall && r < 0.4) return this.startClimbDown(wall);
      if (r < 0.65) return this.fall(this.dir * this.P * 1.1, -this.P * 3);
    }
    this.dir = -this.dir;
    if (chance(0.3)) this.startGround('idle');
    else this.view.setFacing(this.side());
  }

  // Walking toward a window side: maybe climb it (jumping up to grab it if it hangs above).
  tryClimbWall(x0, x1) {
    const inset = this.climbInset;
    for (const w of this.world.wallsCrossed(x0 + this.dir * inset, x1 + this.dir * inset, this.y, this.dir)) {
      if (w.id === this.surfaceId) continue;
      if (w.y1 > this.y - this.P * 0.6) continue;
      if (w.y2 < this.y - this.jumpReach) continue;
      if (Math.abs(w.y1 - w.top) > 2) continue;
      const mountX = w.x + this.dir * this.P * 0.3;
      if (!this.world.surfaceAt(w.id, mountX, 0)) continue;
      if (!chance(this.cfg.climbChance)) continue;
      this.startClimb(w);
      return true;
    }
    return false;
  }

  // ---------- walls ----------

  startClimb(w) {
    this.mode = 'wall';
    this.wall = { id: w.id, side: w.side };
    this.surfaceId = null;
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    const targetY = Math.min(this.y, w.y2 - 2);
    if (this.y - targetY > 3) {
      this.action = 'jumpGrab';
      this.jump = { y0: this.y, y1: targetY, t: 0, dur: 0.3 + ((this.y - targetY) / this.P) * 0.18 };
      this.anim('jump', { facing: 'back', restart: true });
    } else {
      this.action = 'climbUp';
      this.anim('climb', { pose: 'climb', facing: 'back' });
    }
  }

  startClimbDown(w) {
    this.mode = 'wall';
    this.wall = { id: w.id, side: w.side };
    this.surfaceId = null;
    this.y = Math.min(w.y2 - 1, this.y + this.P * 0.5);
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    this.action = 'climbDown';
    this.anim('climb', { pose: 'climb', facing: 'back', speed: -1 });
  }

  updateWall(dt) {
    if (this.action === 'jumpGrab') {
      const j = this.jump;
      j.t += dt;
      const u = Math.min(1, j.t / j.dur);
      this.y = j.y0 + (j.y1 - j.y0) * u - this.P * 0.25 * Math.sin(Math.PI * u);
      if (!this.world.wallAt(this.wall.id, this.wall.side, j.y1)) return this.fall(0, 0);
      const w = this.world.wallAt(this.wall.id, this.wall.side, j.y1);
      this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
      if (u >= 1) {
        this.y = j.y1;
        this.action = 'climbUp';
        this.anim('climb', { pose: 'climb', facing: 'back' });
      }
      return;
    }

    const w = this.validateWall();
    if (!w) return;

    if (this.action === 'climbRest') {
      this.timer -= dt;
      if (this.timer <= 0) {
        this.action = this.resumeAction;
        this.anim('climb', { pose: 'climb', facing: 'back', speed: this.action === 'climbDown' ? -1 : 1 });
      }
      return;
    }

    if (chance(dt * 0.12)) {
      this.resumeAction = this.action;
      this.action = 'climbRest';
      this.timer = rand(0.8, 2);
      this.anim('climbing', { pose: 'climb', facing: 'back' });
      return;
    }

    if (this.action === 'climbUp') {
      this.y -= this.climbSpeed * dt;
      if (this.y <= w.y1) {
        this.y = w.y1;
        const dir = w.side === 'left' ? 1 : -1;
        const mountX = w.x + dir * this.P * 0.3;
        const s = Math.abs(w.y1 - w.top) <= 2 ? this.world.surfaceAt(w.id, mountX, 0) : null;
        if (!s) return this.startClimbDown(w);
        this.mode = 'ground';
        this.surfaceId = w.id;
        this.wall = null;
        this.dir = dir;
        this.x = mountX;
        this.y = s.y;
        this.action = 'walk';
        this.timer = rand(2, 6);
        this.anim('walk', { facing: this.side() });
      }
    } else {
      const y0 = this.y;
      this.y += this.climbSpeed * dt;
      const s = this.world.landing(this.x, y0, this.y);
      if (s) {
        this.dir = w.side === 'left' ? -1 : 1;
        return this.land(s);
      }
      if (this.y > w.y2) this.fall(0, 0);
    }
  }

  // ---------- air ----------

  fall(vx, vy) {
    this.mode = 'air';
    this.surfaceId = null;
    this.wall = null;
    this.vx = vx;
    this.vy = vy;
    this.action = 'fall';
    this.anim('jump', { facing: vx ? this.side() : 'front' });
  }

  updateAir(dt) {
    const W = this.world.width;
    const H = this.world.height;
    this.vy = Math.min(this.vy + this.gravity * dt, this.P * 25);
    const y0 = this.y;
    this.y += this.vy * dt;
    this.x += this.vx * dt;
    if (this.x < this.P * 0.2 || this.x > W - this.P * 0.2) {
      this.x = clamp(this.x, this.P * 0.2, W - this.P * 0.2);
      this.vx = 0;
    }
    if (this.vy >= 0) {
      const s = this.world.landing(this.x, y0, this.y);
      if (s) return this.land(s);
    }
    if (this.y >= H) this.land(this.world.surfaces[0]);
  }

  // ---------- main ----------

  update(dt) {
    if (this.x === null || !this.world.ready) return;
    this.awake += dt;
    if (this.mode === 'ground') {
      if (this.action === 'land') {
        this.validateGround();
        this.timer -= dt;
        if (this.timer <= 0) this.startGround(chance(0.6) ? 'walk' : 'idle');
      } else {
        this.updateGround(dt);
      }
    } else if (this.mode === 'wall') {
      this.updateWall(dt);
    } else {
      this.updateAir(dt);
    }
  }
}

function drawDebug(canvas, world) {
  canvas.width = world.width;
  canvas.height = world.height;
  const g = canvas.getContext('2d');
  g.clearRect(0, 0, canvas.width, canvas.height);
  g.lineWidth = 3;
  g.strokeStyle = 'rgba(0,255,90,0.8)';
  for (const s of world.surfaces) {
    g.beginPath();
    g.moveTo(s.x1, s.y - 1.5);
    g.lineTo(s.x2, s.y - 1.5);
    g.stroke();
  }
  g.strokeStyle = 'rgba(255,150,0,0.8)';
  for (const w of world.walls) {
    g.beginPath();
    g.moveTo(w.x, w.y1);
    g.lineTo(w.x, w.y2);
    g.stroke();
  }
}

function trayIcon(view) {
  const c = document.createElement('canvas');
  const size = 64;
  c.width = c.height = size;
  const r = devicePixelRatio;
  const P = view.petHeight;
  const sx = (view.feetX - P * 0.3) * r;
  const sy = (view.feetY - P * 1.02) * r;
  c.getContext('2d').drawImage(view.canvas, sx, sy, P * 0.6 * r, P * 0.6 * r, 0, 0, size, size);
  return c.toDataURL('image/png');
}

export async function startPet(files, config) {
  const canvas = document.getElementById('pet');
  const debugCanvas = document.getElementById('debug');
  const view = await PetView.create(files, config.petHeight, canvas);
  const world = new World(config.petHeight);
  const pet = new Pet(view, world, config);

  view.play('idle', { fade: 0 });
  view.update(0);
  window.petAPI.setTrayIcon(trayIcon(view));

  window.petAPI.onWorld((data) => {
    const moved = world.update(data);
    pet.onWorldUpdate(moved);
    if (config.debug) drawDebug(debugCanvas, world);
  });

  let last = performance.now();
  const frame = (now) => {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    pet.update(dt);
    view.update(dt);
    if (pet.x !== null) {
      const left = Math.round(pet.x - view.feetX);
      const top = Math.round(pet.y - view.feetY);
      canvas.style.transform = `translate(${left}px, ${top}px)`;
    }
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}

