// Exposes the host API (Tauri commands/events) to the rest of the renderer.
const { invoke } = window.__TAURI__.core;
const { listen } = window.__TAURI__.event;

window.petAPI = {
  getConfig: () => invoke('get_config'),
  loadModel: () => invoke('load_model'),
  onWorld: (cb) => listen('world', (e) => cb(e.payload)),
  savePreview: (name, dataUrl) => invoke('save_preview', { name, dataUrl }),
  previewDone: () => invoke('preview_done'),
  setTrayIcon: (dataUrl) => invoke('set_tray_icon', { dataUrl }),
  log: (...args) => invoke('log', { msg: args.map(String).join(' ') }),
};

import './bridge.js';

window.addEventListener('error', (e) => window.petAPI.log('error', e.message, e.filename, e.lineno));
window.addEventListener('unhandledrejection', (e) => window.petAPI.log('rejection', String(e.reason?.stack || e.reason)));

const config = await window.petAPI.getConfig();
const files = await window.petAPI.loadModel();

if (window.__PET_PREVIEW__) {
  const { runPreview } = await import('./preview.js');
  await runPreview(files, config);
} else {
  const { startPet } = await import('./pet.js');
  await startPet(files, config);
}

fn main() {
    tauri_build::build()
}

