use std::mem::{size_of, zeroed};
use std::ptr::{null, null_mut};

use windows_sys::Win32::Foundation::{BOOL, HWND, LPARAM, RECT, TRUE};
use windows_sys::Win32::Graphics::Dwm::{DwmGetWindowAttribute, DWMWA_CLOAKED, DWMWA_EXTENDED_FRAME_BOUNDS};
use windows_sys::Win32::Graphics::Gdi::{EnumDisplayMonitors, GetMonitorInfoW, HDC, HMONITOR, MONITORINFO};
use windows_sys::Win32::UI::HiDpi::{GetDpiForMonitor, MDT_EFFECTIVE_DPI};
use windows_sys::Win32::UI::WindowsAndMessaging::*;

#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Rect {
    pub left: i32,
    pub top: i32,
    pub right: i32,
    pub bottom: i32,
}

impl From<RECT> for Rect {
    fn from(r: RECT) -> Self {
        Rect { left: r.left, top: r.top, right: r.right, bottom: r.bottom }
    }
}

pub struct WindowInfo {
    pub id: isize,
    pub rect: Rect,
    pub maximized: bool,
}

pub struct MonitorInfo {
    pub bounds: Rect,
    pub work: Rect,
    pub primary: bool,
    pub scale: f64,
}

const IGNORED_CLASSES: &[&str] = &[
    "Progman",
    "WorkerW",
    "Shell_TrayWnd",
    "Shell_SecondaryTrayWnd",
    "NotifyIconOverflowWindow",
    "Windows.UI.Core.CoreWindow",
    "ForegroundStaging",
    "MultitaskingViewFrame",
    "XamlExplorerHostIslandWindow",
    "TopLevelWindowForOverflowXamlIsland",
];

unsafe fn class_name(hwnd: HWND) -> String {
    let mut buf = [0u16; 256];
    let n = GetClassNameW(hwnd, buf.as_mut_ptr(), buf.len() as i32);
    String::from_utf16_lossy(&buf[..n.max(0) as usize])
}

unsafe fn is_cloaked(hwnd: HWND) -> bool {
    let mut cloaked: u32 = 0;
    DwmGetWindowAttribute(hwnd, DWMWA_CLOAKED as _, &mut cloaked as *mut u32 as *mut _, size_of::<u32>() as u32) == 0
        && cloaked != 0
}

unsafe fn frame_rect(hwnd: HWND) -> Option<Rect> {
    let mut r: RECT = zeroed();
    if DwmGetWindowAttribute(hwnd, DWMWA_EXTENDED_FRAME_BOUNDS as _, &mut r as *mut RECT as *mut _, size_of::<RECT>() as u32) == 0 {
        return Some(r.into());
    }
    if GetWindowRect(hwnd, &mut r) != 0 {
        return Some(r.into());
    }
    None
}

/// Visible top-level app windows, topmost first. Rects are physical screen pixels.
pub fn list_windows(ignore_pid: u32) -> Vec<WindowInfo> {
    let mut out = Vec::new();
    unsafe {
        let mut hwnd = GetTopWindow(null_mut());
        let mut guard = 0;
        while !hwnd.is_null() && guard < 4000 {
            guard += 1;
            let h = hwnd;
            hwnd = GetWindow(h, GW_HWNDNEXT);

            if IsWindowVisible(h) == 0 || IsIconic(h) != 0 {
                continue;
            }
            let style = GetWindowLongW(h, GWL_STYLE) as u32;
            if style & WS_CHILD != 0 {
                continue;
            }
            let ex = GetWindowLongW(h, GWL_EXSTYLE) as u32;
            if ex & WS_EX_TRANSPARENT != 0 {
                continue;
            }
            if ex & (WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE) != 0 && ex & WS_EX_APPWINDOW == 0 {
                continue;
            }
            if GetWindowTextLengthW(h) == 0 {
                continue;
            }
            if IGNORED_CLASSES.contains(&class_name(h).as_str()) || is_cloaked(h) {
                continue;
            }
            let mut pid = 0u32;
            GetWindowThreadProcessId(h, &mut pid);
            if pid == ignore_pid {
                continue;
            }
            let Some(rect) = frame_rect(h) else { continue };
            if rect.right - rect.left < 60 || rect.bottom - rect.top < 40 {
                continue;
            }
            out.push(WindowInfo { id: h as isize, rect, maximized: IsZoomed(h) != 0 });
        }
    }
    out
}

unsafe extern "system" fn collect_monitor(hm: HMONITOR, _hdc: HDC, _clip: *mut RECT, data: LPARAM) -> BOOL {
    let list = &mut *(data as *mut Vec<MonitorInfo>);
    let mut mi: MONITORINFO = zeroed();
    mi.cbSize = size_of::<MONITORINFO>() as u32;
    if GetMonitorInfoW(hm, &mut mi) != 0 {
        let (mut dx, mut dy) = (96u32, 96u32);
        GetDpiForMonitor(hm, MDT_EFFECTIVE_DPI, &mut dx, &mut dy);
        list.push(MonitorInfo {
            bounds: mi.rcMonitor.into(),
            work: mi.rcWork.into(),
            primary: mi.dwFlags & MONITORINFOF_PRIMARY != 0,
            scale: dx as f64 / 96.0,
        });
    }
    TRUE
}

/// All monitors, primary first. Rects are physical pixels.
pub fn monitors() -> Vec<MonitorInfo> {
    let mut list: Vec<MonitorInfo> = Vec::new();
    unsafe {
        EnumDisplayMonitors(null_mut(), null(), Some(collect_monitor), &mut list as *mut _ as LPARAM);
    }
    list.sort_by_key(|m| (!m.primary, m.bounds.left, m.bounds.top));
    list
}

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod win32;

use base64::{engine::general_purpose::STANDARD, Engine};
use serde::Serialize;
use serde_json::{json, Value};
use std::{
    fs,
    path::{Path, PathBuf},
    thread,
    time::Duration,
};
use tauri::{
    image::Image,
    menu::{Menu, MenuItem},
    tray::TrayIconBuilder,
    AppHandle, Emitter, Manager, PhysicalPosition, PhysicalSize, State, WebviewUrl, WebviewWindowBuilder,
};

struct PetState {
    root: PathBuf,
    config: Value,
    shots: Option<Value>,
}

#[derive(Serialize, Clone)]
struct WindowOut {
    id: String,
    x: f64,
    y: f64,
    w: f64,
    h: f64,
    maximized: bool,
}

#[derive(Serialize, Clone)]
struct WorldOut {
    width: f64,
    height: f64,
    windows: Vec<WindowOut>,
    fullscreen: bool,
}

fn default_config() -> Value {
    json!({
        "modelDir": "DaL_Kurumi",
        "display": "primary",
        "petHeight": 110,
        "walkSpeed": 0.5,
        "runSpeed": 1.4,
        "climbSpeed": 0.5,
        "gravity": 16,
        "jumpReach": 1.6,
        "climbChance": 0.6,
        "emotes": ["extra0", "extra1", "extra2", "extra3", "extra4", "extra6"],
        "debug": false
    })
}

// config.json and the model folder live next to the .exe; in development they are a few levels up.
fn find_root() -> PathBuf {
    let mut candidates = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        candidates.extend(exe.ancestors().skip(1).take(5).map(Path::to_path_buf));
    }
    if let Ok(cwd) = std::env::current_dir() {
        candidates.extend(cwd.ancestors().take(2).map(Path::to_path_buf));
    }
    candidates
        .iter()
        .find(|d| d.join("config.json").exists())
        .cloned()
        .unwrap_or_else(|| candidates.first().cloned().unwrap_or_default())
}

fn load_config(root: &Path) -> Value {
    let mut config = default_config();
    if let Ok(text) = fs::read_to_string(root.join("config.json")) {
        if let Ok(Value::Object(user)) = serde_json::from_str::<Value>(&text) {
            for (k, v) in user {
                config[k] = v;
            }
        }
    }
    config
}

fn parse_shots(arg: &str) -> Value {
    Value::Array(
        arg.split(',')
            .map(|s| {
                let mut parts = s.split(':');
                let anim = parts.next().unwrap_or("idle");
                let pose = parts.next().unwrap_or("stand");
                let mut facings: Vec<&str> = parts.collect();
                if facings.is_empty() {
                    facings.push("front");
                }
                json!({ "anim": anim, "pose": pose, "facings": facings })
            })
            .collect(),
    )
}

fn decode_data_url(data_url: &str) -> Result<Vec<u8>, String> {
    let b64 = data_url.split_once(',').map(|(_, b)| b).unwrap_or(data_url);
    STANDARD.decode(b64).map_err(|e| e.to_string())
}

#[tauri::command]
fn get_config(state: State<PetState>) -> Value {
    let mut config = state.config.clone();
    if let Some(shots) = &state.shots {
        config["previewShots"] = shots.clone();
    }
    config
}

#[tauri::command]
fn load_model(state: State<PetState>) -> Result<Value, String> {
    let dir_name = state.config["modelDir"].as_str().unwrap_or("DaL_Kurumi");
    let dir = if Path::new(dir_name).is_absolute() { PathBuf::from(dir_name) } else { state.root.join(dir_name) };
    let files: Vec<String> = fs::read_dir(&dir)
        .map_err(|e| format!("{}: {e}", dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .collect();
    let has = |name: &str| files.iter().any(|f| f == name);
    let read_json = |name: &str| -> Result<Value, String> {
        let text = fs::read_to_string(dir.join(name)).map_err(|e| format!("{name}: {e}"))?;
        serde_json::from_str(&text).map_err(|e| format!("{name}: {e}"))
    };

    let geometry = if has("main.json") {
        "main.json".to_string()
    } else {
        files
            .iter()
            .find(|f| f.ends_with(".json") && !f.contains("animation"))
            .cloned()
            .ok_or("geometry .json not found")?
    };

    let mut anims: Vec<String> = ["main.animation.json", "extra.animation.json"]
        .iter()
        .filter(|f| has(f))
        .map(|f| f.to_string())
        .collect();
    for f in &files {
        if f.ends_with(".animation.json") && !anims.contains(f) && !f.starts_with("arm") && !f.starts_with("tac") {
            anims.push(f.clone());
        }
    }

    let texture = if has("texture.png") {
        "texture.png".to_string()
    } else {
        files.iter().find(|f| f.ends_with(".png")).cloned().ok_or("texture .png not found")?
    };
    let tex_bytes = fs::read(dir.join(&texture)).map_err(|e| e.to_string())?;

    Ok(json!({
        "geometry": read_json(&geometry)?,
        "animations": anims.iter().map(|f| read_json(f)).collect::<Result<Vec<_>, _>>()?,
        "texture": format!("data:image/png;base64,{}", STANDARD.encode(tex_bytes)),
    }))
}

#[tauri::command]
fn save_preview(state: State<PetState>, name: String, data_url: String) -> Result<(), String> {
    let dir = state.root.join("preview");
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let safe: String = name.chars().map(|c| if c.is_alphanumeric() || c == '_' { c } else { '_' }).collect();
    fs::write(dir.join(format!("{safe}.png")), decode_data_url(&data_url)?).map_err(|e| e.to_string())
}

#[tauri::command]
fn preview_done(app: AppHandle) {
    app.exit(0);
}

#[tauri::command]
fn set_tray_icon(app: AppHandle, data_url: String) -> Result<(), String> {
    let bytes = decode_data_url(&data_url)?;
    let image = Image::from_bytes(&bytes).map_err(|e| e.to_string())?;
    if let Some(tray) = app.tray_by_id("main") {
        tray.set_icon(Some(image)).map_err(|e| e.to_string())?;
    }
    Ok(())
}

#[tauri::command]
fn log(msg: String) {
    println!("{msg}");
}

// Keeps the overlay covering the chosen monitor's work area and streams window geometry to the renderer.
fn start_world_polling(app: AppHandle, display: Option<usize>) {
    thread::spawn(move || {
        let pid = std::process::id();
        let mut last_work = None;
        let mut tick: u64 = 0;
        loop {
            thread::sleep(Duration::from_millis(40));
            tick += 1;
            let Some(win) = app.get_webview_window("main") else { continue };
            let monitors = win32::monitors();
            let Some(mon) = display.and_then(|i| monitors.get(i)).or_else(|| monitors.first()) else { continue };
            let work = mon.work;
            let bounds = mon.bounds;
            let scale = mon.scale;

            if last_work != Some(work) {
                let _ = win.set_position(PhysicalPosition::new(work.left, work.top));
                let _ = win.set_size(PhysicalSize::new((work.right - work.left) as u32, (work.bottom - work.top) as u32));
                last_work = Some(work);
            }
            if tick % 75 == 0 {
                let _ = win.set_always_on_top(true);
            }

            let mut windows = Vec::new();
            let mut fullscreen = false;
            for w in win32::list_windows(pid) {
                let r = w.rect;
                if windows.is_empty()
                    && r.left <= bounds.left
                    && r.top <= bounds.top
                    && r.right >= bounds.right
                    && r.bottom >= bounds.bottom
                {
                    fullscreen = true;
                }
                if r.right < work.left || r.left > work.right || r.bottom < work.top || r.top > work.bottom {
                    continue;
                }
                windows.push(WindowOut {
                    id: w.id.to_string(),
                    x: (r.left - work.left) as f64 / scale,
                    y: (r.top - work.top) as f64 / scale,
                    w: (r.right - r.left) as f64 / scale,
                    h: (r.bottom - r.top) as f64 / scale,
                    maximized: w.maximized,
                });
            }

            let _ = app.emit(
                "world",
                WorldOut {
                    width: (work.right - work.left) as f64 / scale,
                    height: (work.bottom - work.top) as f64 / scale,
                    windows,
                    fullscreen,
                },
            );
        }
    });
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let preview = args.iter().any(|a| a == "--preview");
    let shots = args.iter().find_map(|a| a.strip_prefix("--shots=")).map(parse_shots);
    let root = find_root();
    let config = load_config(&root);
    let display = config["display"].as_u64().map(|n| n as usize);

    tauri::Builder::default()
        .manage(PetState { root, config, shots })
        .invoke_handler(tauri::generate_handler![get_config, load_model, save_preview, preview_done, set_tray_icon, log])
        .setup(move |app| {
            let win = WebviewWindowBuilder::new(app, "main", WebviewUrl::App("index.html".into()))
                .title("Desktop Pet")
                .transparent(true)
                .decorations(false)
                .shadow(false)
                .resizable(false)
                .always_on_top(!preview)
                .skip_taskbar(true)
                .focused(false)
                .visible(!preview)
                .inner_size(900.0, 600.0)
                .initialization_script(if preview { "window.__PET_PREVIEW__ = true;" } else { "" })
                .build()?;

            if !preview {
                win.set_ignore_cursor_events(true)?;
                let quit = MenuItem::with_id(app, "quit", "Sair", true, None::<&str>)?;
                let menu = Menu::with_items(app, &[&quit])?;
                let mut tray = TrayIconBuilder::with_id("main").tooltip("Desktop Pet").menu(&menu).on_menu_event(
                    |app, event| {
                        if event.id() == "quit" {
                            app.exit(0);
                        }
                    },
                );
                if let Some(icon) = app.default_window_icon() {
                    tray = tray.icon(icon.clone());
                }
                tray.build(app)?;
                start_world_polling(app.handle().clone(), display);
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("failed to run Desktop Pet");
}

