    win32::make_thread_dpi_aware();
    let pid = std::process::id();

if (config.debug) {
  window.petAPI.log(`view dpr=${devicePixelRatio} inner=${innerWidth}x${innerHeight}`);
  let lastState = '';

// Physical pixels; the renderer divides by its devicePixelRatio (the only reliable scale
// under Windows custom scaling, where Win32 DPI queries report 96).
let scale = 1.0;

window.petAPI.onWorld((raw) => {
  const s = devicePixelRatio;
  const data = {
    ...raw,
    width: raw.width / s,
    height: raw.height / s,
    windows: raw.windows.map((w) => ({ ...w, x: w.x / s, y: w.y / s, w: w.w / s, h: w.h / s })),
  };
  const moved = world.update(data);

  await window.petAPI.savePreview('_sheet', sheet.toDataURL('image/png'));
  await window.petAPI.savePreview('_icon', renderIcon(view));
  window.petAPI.previewDone();
}

// Transparent square portrait (head and shoulders, facing front) for the app icon.
function renderIcon(view) {
  view.setPose('stand');
  view.setFacing('front');
  view.play('idle', { restart: true, fade: 0 });
  view.update(0);
  const r = devicePixelRatio;
  const P = view.petHeight;
  const size = P * 0.62;
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const g = c.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.drawImage(view.canvas, (view.feetX - size / 2) * r, (view.feetY - P * 1.03) * r, size * r, size * r, 0, 0, 512, 512);
  return c.toDataURL('image/png');

