import * as THREE from './vendor/three.module.js';
import { buildModel } from './model.js';
import { loadClips, Animator } from './animation.js';

// Model faces -Z; the camera looks at it from +Z.
const YAW = { front: Math.PI, back: 0, right: -Math.PI / 2, left: Math.PI / 2 };

// Body orientations Minecraft applies outside the animation (ladder crawl, lying in bed).
// ground rests the lowest point of the posed model on the surface (sitting/lying animations are
// authored for a seat or bed and would float otherwise); center keeps it horizontally centered.
export const POSES = {
  stand: { pitch: 0, ground: false, center: false },
  sit: { pitch: 0, ground: true, center: false },
  climb: { pitch: 90, ground: true, center: true },
  lie: { pitch: 90, ground: true, center: true },
};

function loadTexture(dataUrl) {
  return new Promise((resolve, reject) => {
    new THREE.TextureLoader().load(
      dataUrl,
      (t) => {
        t.magFilter = THREE.NearestFilter;
        t.minFilter = THREE.NearestFilter;
        t.generateMipmaps = false;
        t.colorSpace = THREE.SRGBColorSpace;
        t.flipY = true;
        resolve(t);
      },
      undefined,
      reject,
    );
  });
}

export class PetView {
  static async create(files, petHeight, canvas) {
    const texture = await loadTexture(files.texture);
    const model = buildModel(files.geometry, texture);
    const clips = loadClips(files.animations);
    return new PetView(model, clips, petHeight, canvas);
  }

  constructor(model, clips, petHeight, canvas) {
    this.model = model;
    this.animator = new Animator(model.bones, clips);
    this.modelHeight = Math.max(1, model.box.max.y - Math.min(0, model.box.min.y));
    this.canvas = canvas;

    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, preserveDrawingBuffer: true });
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;

    this.scene = new THREE.Scene();
    this.anchor = new THREE.Group();
    this.yawGroup = new THREE.Group();
    this.poseGroup = new THREE.Group();
    this.poseGroup.add(model.root);
    this.yawGroup.add(this.poseGroup);
    this.anchor.add(this.yawGroup);
    this.scene.add(this.anchor);
    this.camera = new THREE.OrthographicCamera();
    this.camera.position.set(0, 0, 200);
    this.camera.lookAt(0, 0, 0);

    this.box = new THREE.Box3();
    this.bounds = { top: petHeight, centerX: 0 };
    this.pose = 'stand';
    this.snap = true;
    this.resize(petHeight);

    this.facing = null;
    this.setFacing('front');
  }

  // Pet height in CSS pixels; everything else scales from it.
  resize(petHeight) {
    const P = (this.petHeight = petHeight);
    this.ppu = P / this.modelHeight;
    this.width = Math.round(P * 2.4);
    this.height = Math.round(P * 1.8);
    this.feetX = this.width / 2;
    this.feetY = Math.round(this.height - P * 0.3);

    this.renderer.setPixelRatio(devicePixelRatio);
    this.renderer.setSize(this.width, this.height, false);
    this.canvas.style.width = this.width + 'px';
    this.canvas.style.height = this.height + 'px';

    const u = 1 / this.ppu;
    Object.assign(this.camera, {
      left: -this.feetX * u,
      right: (this.width - this.feetX) * u,
      top: this.feetY * u,
      bottom: -(this.height - this.feetY) * u,
      near: 0.1,
      far: 1000,
    });
    this.camera.updateProjectionMatrix();
    this.snap = true;
  }

  setFacing(facing) {
    if (facing === this.facing) return;
    this.facing = facing;
    this.yawGroup.rotation.set(0, YAW[facing] ?? 0, 0);
    if (POSES[this.pose].center) this.snap = true;
  }

  // Returns true when the body orientation changed (callers skip the crossfade then).
  setPose(pose) {
    const name = pose in POSES ? pose : 'stand';
    const pitchChanged = POSES[name].pitch !== POSES[this.pose].pitch;
    this.pose = name;
    this.poseGroup.rotation.set(POSES[name].pitch * (Math.PI / 180), 0, 0);
    if (pitchChanged) this.snap = true;
    return pitchChanged;
  }

  play(name, opts) {
    this.animator.play(name, opts);
  }

  // Posed model extents relative to the feet, in model units, ignoring the current anchor offset.
  measure() {
    this.scene.updateMatrixWorld(true);
    const b = this.box.setFromObject(this.yawGroup, true);
    const a = this.anchor.position;
    return { minX: b.min.x - a.x, maxX: b.max.x - a.x, minY: b.min.y - a.y, maxY: b.max.y - a.y };
  }

  reanchor() {
    this.snap = true;
    this.updateAnchor(0);
  }

  updateAnchor(dt) {
    const m = this.measure();
    const p = POSES[this.pose];
    const tx = p.center ? -(m.minX + m.maxX) / 2 : 0;
    const ty = p.ground ? -m.minY : 0;
    const a = this.anchor.position;
    if (this.snap) {
      a.set(tx, ty, 0);
      this.snap = false;
    } else {
      const k = 1 - Math.exp(-14 * dt);
      a.set(a.x + (tx - a.x) * k, a.y + (ty - a.y) * k, 0);
    }
    this.bounds = { top: (m.maxY + a.y) * this.ppu, centerX: ((m.minX + m.maxX) / 2 + a.x) * this.ppu };
  }

  update(dt) {
    this.animator.update(dt);
    this.updateAnchor(dt);
    this.renderer.render(this.scene, this.camera);
  }

  // Whether the pet is drawn near (x, y), in canvas CSS pixels.
  hitTest(x, y, radius = 3) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return false;
    const gl = this.renderer.getContext();
    const d = devicePixelRatio;
    const s = Math.max(1, Math.round(radius * d)) * 2 + 1;
    const cw = gl.drawingBufferWidth;
    const ch = gl.drawingBufferHeight;
    const px = Math.min(Math.max(Math.round(x * d) - (s >> 1), 0), cw - s);
    const py = Math.min(Math.max(Math.round((this.height - y) * d) - (s >> 1), 0), ch - s);
    const buf = new Uint8Array(s * s * 4);
    gl.readPixels(px, py, s, s, gl.RGBA, gl.UNSIGNED_BYTE, buf);
    for (let i = 3; i < buf.length; i += 4) if (buf[i] > 40) return true;
    return false;
  }

  dispose() {
    this.model.material.map?.dispose();
    this.model.material.dispose();
    this.scene.traverse((o) => o.geometry?.dispose());
    this.renderer.dispose();
    this.renderer.forceContextLoss();
  }
}

const rand = (a, b) => a + Math.random() * (b - a);
const chance = (p) => Math.random() < p;
const clamp = (v, a, b) => Math.min(Math.max(v, a), b);

function pickWeighted(weights) {
  const entries = Object.entries(weights).filter(([, w]) => w > 0);
  let r = Math.random() * entries.reduce((s, [, w]) => s + w, 0);
  for (const [k, w] of entries) {
    if ((r -= w) <= 0) return k;
  }
  return entries[0][0];
}

export class Pet {
  constructor(view, world, cfg) {
    this.view = view;
    this.world = world;
    this.cfg = cfg;
    this.emotes = (cfg.emotes || []).filter((e) => view.animator.has(e));
    this.setSize(cfg.petHeight);

    this.x = null;
    this.y = null;
    this.dir = 1;
    this.mode = 'air';
    this.surfaceId = null;
    this.wall = null;
    this.vx = 0;
    this.vy = 0;
    this.action = null;
    this.timer = 0;
    this.awake = 0;
    this.jump = null;
    this.hold = null;
    this.thrown = false;
    this.paused = false;

    // Visual tilt (radians) around tiltPivot (offset from the feet), driven while being carried.
    this.tilt = 0;
    this.tiltPivot = { x: 0, y: 0 };

    // 0..100. Energy drains while awake and refills while sleeping; happiness drifts to neutral.
    this.energy = rand(70, 95);
    this.happiness = 70;
    this.moodTimer = rand(20, 40);
    this.listeners = [];
  }

  on(fn) {
    this.listeners.push(fn);
  }

  emit(type, data = {}) {
    for (const fn of this.listeners) fn(type, data);
  }

  setSize(P) {
    const cfg = this.cfg;
    this.P = P;
    this.walkSpeed = cfg.walkSpeed * P;
    this.runSpeed = cfg.runSpeed * P;
    this.climbSpeed = cfg.climbSpeed * P;
    this.gravity = cfg.gravity * P;
    this.jumpReach = cfg.jumpReach * P;
    this.climbInset = P * 0.14;
    this.edgeMargin = P * 0.08;
    if (this.world.petHeight !== P) {
      this.world.petHeight = P;
      if (this.world.ready) this.world.rebuild([...this.world.windows.values()]);
    }
    if (this.mode === 'ground') this.validateGround();
    else if (this.mode === 'wall' && this.action !== 'jumpGrab') this.validateWall();
  }

  anim(name, { pose = 'stand', facing = 'front', speed = 1, restart = false } = {}) {
    const snapped = this.view.setPose(pose);
    this.view.setFacing(facing);
    this.view.play(name, { restart, fade: snapped ? 0 : 0.18, speed });
  }

  side() {
    return this.dir > 0 ? 'right' : 'left';
  }

  spawn(x) {
    const W = this.world.width;
    this.x = typeof x === 'number' ? clamp(x, this.P, W - this.P) : rand(this.P, W - this.P);
    this.y = this.P * 1.2;
    this.fall(0, 0);
  }

  // ---------- controls ----------

  pause() {
    if (this.paused) return;
    this.paused = true;
    if (this.mode === 'ground') {
      if (this.action === 'sit' || this.action === 'sleep' || this.action === 'dizzy') this.timer = Infinity;
      else if (this.action !== 'land') this.startGround('idle');
    } else if (this.mode === 'wall' && this.action !== 'jumpGrab') {
      this.restOnWall(Infinity);
    }
    this.emit('pause');
  }

  resume() {
    if (!this.paused) return;
    this.paused = false;
    if (this.mode === 'ground' && this.action !== 'sleep') this.timer = Math.min(this.timer, rand(0.3, 1));
    else if (this.mode === 'ground') this.timer = rand(3, 8);
    else if (this.mode === 'wall' && this.action === 'climbRest') this.timer = 0.3;
    this.emit('resume');
  }

  restart() {
    this.paused = false;
    this.hold = null;
    this.tilt = 0;
    this.spawn();
    this.emit('restart');
  }

  // Short click on the pet.
  pat() {
    this.happiness = clamp(this.happiness + 8, 0, 100);
    if (this.mode !== 'ground') return this.emit('pet');
    if (this.action === 'sleep') {
      this.startGround('idle');
      return this.emit('wake', { startled: true });
    }
    if (this.action !== 'dizzy' && this.action !== 'land') {
      this.action = 'idle';
      this.timer = this.paused ? Infinity : rand(2, 3.5);
      this.anim('idle');
    }
    this.emit('pet');
  }

  // ---------- carried by the mouse ----------

  // (cx, cy): cursor position; the pet keeps its offset from the cursor while carried.
  grab(cx, cy) {
    const ox = this.x - cx;
    const oy = this.y - cy;
    const comY = oy - this.P * 0.5;
    this.hold = { cx, cy, ox, oy, px: cx, v: 0, pv: 0, w: 0, t: 0, hist: [], long: false, L: Math.max(this.P * 0.35, Math.abs(comY)) };
    this.tiltPivot = { x: -ox, y: -oy };
    this.mode = 'held';
    this.surfaceId = null;
    this.wall = null;
    this.jump = null;
    this.action = 'held';
    this.anim('jump', { facing: 'front' });
    this.happiness = clamp(this.happiness - 2, 0, 100);
    this.emit('grab');
  }

  drag(cx, cy) {
    if (!this.hold) return;
    this.hold.cx = cx;
    this.hold.cy = cy;
  }

  release() {
    const h = this.hold;
    if (!h) return;
    let vx = 0;
    let vy = 0;
    const a = h.hist[0];
    const b = h.hist[h.hist.length - 1];
    if (a && b && b.t - a.t > 0.02) {
      vx = (b.x - a.x) / (b.t - a.t);
      vy = (b.y - a.y) / (b.t - a.t);
    }
    const max = this.P * 30;
    const speed = Math.hypot(vx, vy);
    if (speed > max) {
      vx *= max / speed;
      vy *= max / speed;
    }
    this.hold = null;
    if (Math.abs(vx) > this.P) this.dir = Math.sign(vx);
    this.fall(vx, vy);
    this.thrown = true;
    const s = Math.min(speed, max) / this.P;
    if (s > 8) this.happiness = clamp(this.happiness - 4, 0, 100);
    this.emit('release', { speed: s });
  }

  updateHeld(dt) {
    const h = this.hold;
    h.t += dt;
    const vx = dt > 0 ? (h.cx - h.px) / dt : 0;
    h.px = h.cx;
    h.v += (vx - h.v) * Math.min(1, dt * 20);
    const ax = clamp((h.v - h.pv) / Math.max(dt, 1e-3), -80 * this.P, 80 * this.P);
    h.pv = h.v;
    // Pendulum hanging from the cursor, pushed by the cursor's horizontal acceleration.
    const alpha = (-(this.gravity / h.L) * Math.sin(this.tilt) + (ax / h.L) * Math.cos(this.tilt)) - 3 * h.w;
    h.w += alpha * dt;
    this.tilt = clamp(this.tilt + h.w * dt, -1.2, 1.2);
    this.x = h.cx + h.ox;
    this.y = h.cy + h.oy;
    h.hist.push({ t: h.t, x: h.cx, y: h.cy });
    while (h.hist.length > 2 && h.t - h.hist[0].t > 0.1) h.hist.shift();
    if (!h.long && h.t > 5) {
      h.long = true;
      this.emit('heldLong');
    }
  }

  // ---------- world sync ----------

  onWorldUpdate(moved) {
    if (this.x === null) return this.spawn(this.cfg.spawnX);
    if (this.mode === 'ground') {
      const m = moved.get(this.surfaceId);
      if (m) {
        this.x += m.dx;
        this.y += m.dy;
      }
      this.validateGround();
    } else if (this.mode === 'wall') {
      const m = moved.get(this.wall.id);
      if (m) {
        this.x += m.dx;
        this.y += m.dy;
        if (this.jump) this.jump.y1 += m.dy;
      }
      if (this.action !== 'jumpGrab') this.validateWall();
    }
  }

  validateGround() {
    const s = this.world.surfaceAt(this.surfaceId, this.x, 2);
    if (!s) {
      this.fall(0, 0);
      return null;
    }
    this.y = s.y;
    this.x = clamp(this.x, Math.max(s.x1, this.P * 0.15), Math.min(s.x2, this.world.width - this.P * 0.15));
    return s;
  }

  validateWall() {
    const w = this.world.wallAt(this.wall.id, this.wall.side, this.y);
    if (!w) {
      this.fall(0, 0);
      return null;
    }
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    return w;
  }

  // ---------- ground ----------

  land(s, impact = 0) {
    const thrown = this.thrown;
    this.mode = 'ground';
    this.surfaceId = s.id;
    this.y = s.y;
    this.vx = this.vy = 0;
    this.thrown = false;
    if (impact > this.P * 11) {
      this.action = 'dizzy';
      this.timer = this.paused ? Infinity : rand(2.2, 3.2);
      this.happiness = clamp(this.happiness - 6, 0, 100);
      this.anim('sit', { pose: 'sit', facing: 'front' });
      this.emit('hardLand', { thrown });
      return;
    }
    this.action = 'land';
    this.timer = 0.35;
    this.anim('idle');
    this.emit('land', { thrown, impact: impact / this.P });
  }

  startGround(kind) {
    this.action = kind;
    const f = this.side();
    switch (kind) {
      case 'walk':
        if (chance(0.35)) this.dir = -this.dir;
        this.timer = rand(3, 9);
        this.anim('walk', { facing: this.side() });
        break;
      case 'run':
        if (chance(0.35)) this.dir = -this.dir;
        this.timer = rand(1.5, 3.5);
        this.anim('run', { facing: this.side() });
        break;
      case 'sit':
        this.timer = rand(6, 15);
        this.anim('sit', { pose: 'sit', facing: chance(0.5) ? 'front' : f });
        break;
      case 'sleep':
        this.timer = rand(20, 45);
        this.awake = 0;
        this.anim('sleep', { pose: 'lie', facing: f });
        break;
      case 'emote': {
        const name = this.emotes[Math.floor(Math.random() * this.emotes.length)];
        const clip = this.view.animator.clips.get(name);
        this.timer = clip.loop === 'loop' ? clip.length * Math.max(1, Math.ceil(2.5 / clip.length)) : clip.length + 0.8;
        this.happiness = clamp(this.happiness + 3, 0, 100);
        this.anim(name, { restart: true });
        break;
      }
      default:
        this.action = 'idle';
        this.timer = rand(2, 5);
        this.anim('idle');
    }
    if (this.paused) this.timer = Infinity;
    this.emit(this.action);
  }

  chooseNext() {
    if (this.paused) return this.startGround('idle');
    const w = { walk: 45, idle: 18, run: 7, sit: 10, emote: 12, sleep: 6, ...this.cfg.actionWeights };
    if (!this.emotes.length) w.emote = 0;
    const e = this.energy;
    if (this.awake < 90 && e >= 40) w.sleep = 0;
    if (e < 50) {
      w.sleep *= e < 25 ? 8 : 2.5;
      w.sit *= 2;
      w.run *= 0.25;
    }
    if (this.happiness > 80) w.emote *= 1.6;
    this.startGround(pickWeighted(w));
  }

  updateGround(dt) {
    const s = this.validateGround();
    if (!s) return;

    if (this.action === 'walk' || this.action === 'run') {
      const speed = this.action === 'run' ? this.runSpeed : this.walkSpeed;
      const nx = this.x + this.dir * speed * dt;
      if (this.tryClimbWall(this.x, nx)) return;

      const lo = Math.max(s.x1 + this.edgeMargin, this.P * 0.2);
      const hi = Math.min(s.x2 - this.edgeMargin, this.world.width - this.P * 0.2);
      if ((this.dir > 0 && nx >= hi) || (this.dir < 0 && nx <= lo)) {
        this.x = clamp(nx, lo, hi);
        this.onEdge(s);
        return;
      }
      this.x = nx;
    }

    if (this.action === 'sleep' && this.energy >= 98) this.timer = 0;
    this.timer -= dt;
    if (this.timer <= 0) {
      const wasSleeping = this.action === 'sleep';
      this.chooseNext();
      if (wasSleeping) this.emit('wake', { startled: false });
    }
  }

  onEdge(s) {
    const win = s.id === 'floor' ? null : this.world.window(s.id);
    const realEdge = win && (this.dir > 0 ? Math.abs(s.x2 - win.right) < 2 : Math.abs(s.x1 - win.x) < 2);
    if (realEdge) {
      const wall = this.world.wallAt(s.id, this.side(), this.y + 4, 0);
      const r = Math.random();
      if (wall && r < 0.4) return this.startClimbDown(wall);
      if (r < 0.65) {
        this.emit('hop');
        return this.fall(this.dir * this.P * 1.1, -this.P * 3);
      }
    }
    this.dir = -this.dir;
    this.emit('edge');
    if (chance(0.3)) this.startGround('idle');
    else this.view.setFacing(this.side());
  }

  // Walking toward a window side: maybe climb it (jumping up to grab it if it hangs above).
  tryClimbWall(x0, x1) {
    const inset = this.climbInset;
    for (const w of this.world.wallsCrossed(x0 + this.dir * inset, x1 + this.dir * inset, this.y, this.dir)) {
      if (w.id === this.surfaceId) continue;
      if (w.y1 > this.y - this.P * 0.6) continue;
      if (w.y2 < this.y - this.jumpReach) continue;
      if (Math.abs(w.y1 - w.top) > 2) continue;
      const mountX = w.x + this.dir * this.P * 0.3;
      if (!this.world.surfaceAt(w.id, mountX, 0)) continue;
      if (!chance(this.cfg.climbChance * (this.energy < 30 ? 0.3 : 1))) continue;
      this.startClimb(w);
      return true;
    }
    return false;
  }

  // ---------- walls ----------

  startClimb(w) {
    this.mode = 'wall';
    this.wall = { id: w.id, side: w.side };
    this.surfaceId = null;
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    const targetY = Math.min(this.y, w.y2 - 2);
    if (this.y - targetY > 3) {
      this.action = 'jumpGrab';
      this.jump = { y0: this.y, y1: targetY, t: 0, dur: 0.3 + ((this.y - targetY) / this.P) * 0.18 };
      this.anim('jump', { facing: 'back', restart: true });
    } else {
      this.action = 'climbUp';
      this.anim('climb', { pose: 'climb', facing: 'back' });
    }
    this.emit('climb');
  }

  startClimbDown(w) {
    this.mode = 'wall';
    this.wall = { id: w.id, side: w.side };
    this.surfaceId = null;
    this.y = Math.min(w.y2 - 1, this.y + this.P * 0.5);
    this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
    this.action = 'climbDown';
    this.anim('climb', { pose: 'climb', facing: 'back', speed: -1 });
  }

  restOnWall(duration) {
    if (this.action !== 'climbRest') this.resumeAction = this.action;
    this.action = 'climbRest';
    this.timer = duration;
    this.anim('climbing', { pose: 'climb', facing: 'back' });
  }

  updateWall(dt) {
    if (this.action === 'jumpGrab') {
      const j = this.jump;
      j.t += dt;
      const u = Math.min(1, j.t / j.dur);
      this.y = j.y0 + (j.y1 - j.y0) * u - this.P * 0.25 * Math.sin(Math.PI * u);
      const w = this.world.wallAt(this.wall.id, this.wall.side, j.y1);
      if (!w) return this.fall(0, 0);
      this.x = w.x + (w.side === 'left' ? -this.climbInset : this.climbInset);
      if (u >= 1) {
        this.y = j.y1;
        this.jump = null;
        this.action = 'climbUp';
        this.anim('climb', { pose: 'climb', facing: 'back' });
      }
      return;
    }

    const w = this.validateWall();
    if (!w) return;

    if (this.paused && this.action !== 'climbRest') return this.restOnWall(Infinity);
    if (this.action === 'climbRest') {
      this.timer -= dt;
      if (this.timer <= 0) {
        this.action = this.resumeAction || 'climbUp';
        this.anim('climb', { pose: 'climb', facing: 'back', speed: this.action === 'climbDown' ? -1 : 1 });
      }
      return;
    }

    if (chance(dt * (this.energy < 30 ? 0.35 : 0.12))) return this.restOnWall(rand(0.8, 2));

    if (this.action === 'climbUp') {
      this.y -= this.climbSpeed * dt;
      if (this.y <= w.y1) {
        this.y = w.y1;
        const dir = w.side === 'left' ? 1 : -1;
        const mountX = w.x + dir * this.P * 0.3;
        const s = Math.abs(w.y1 - w.top) <= 2 ? this.world.surfaceAt(w.id, mountX, 0) : null;
        if (!s) return this.startClimbDown(w);
        this.mode = 'ground';
        this.surfaceId = w.id;
        this.wall = null;
        this.dir = dir;
        this.x = mountX;
        this.y = s.y;
        this.action = 'walk';
        this.timer = rand(2, 6);
        this.anim('walk', { facing: this.side() });
        this.emit('climbTop');
      }
    } else {
      const y0 = this.y;
      this.y += this.climbSpeed * dt;
      const s = this.world.landing(this.x, y0, this.y);
      if (s) {
        this.dir = w.side === 'left' ? -1 : 1;
        return this.land(s);
      }
      if (this.y > w.y2) this.fall(0, 0);
    }
  }

  // ---------- air ----------

  fall(vx, vy) {
    this.mode = 'air';
    this.surfaceId = null;
    this.wall = null;
    this.jump = null;
    this.vx = vx;
    this.vy = vy;
    this.action = 'fall';
    this.anim('jump', { facing: Math.abs(vx) > this.P ? this.side() : 'front' });
  }

  updateAir(dt) {
    const W = this.world.width;
    const H = this.world.height;
    this.vy = Math.min(this.vy + this.gravity * dt, this.P * 25);
    this.vx *= Math.exp(-0.35 * dt);
    const y0 = this.y;
    this.y += this.vy * dt;
    this.x += this.vx * dt;
    const minX = this.P * 0.2;
    const maxX = W - this.P * 0.2;
    if (this.x < minX || this.x > maxX) {
      this.x = clamp(this.x, minX, maxX);
      const hard = Math.abs(this.vx) > this.P * 6;
      this.vx = (this.x === minX ? 1 : -1) * Math.abs(this.vx) * 0.45;
      if (hard) this.emit('bump');
    }
    const top = this.P * 1.05;
    if (this.y < top && this.vy < 0) {
      this.y = top;
      const hard = this.vy < -this.P * 6;
      this.vy = Math.abs(this.vy) * 0.3;
      if (hard) this.emit('bump');
    }
    if (this.vy >= 0) {
      const s = this.world.landing(this.x, y0, this.y);
      if (s) return this.land(s, this.vy);
    }
    if (this.y >= H) this.land(this.world.surfaces[0], this.vy);
  }

  // ---------- main ----------

  updateMood(dt) {
    if (this.mode === 'ground' && this.action === 'sleep') {
      this.energy += 1.6 * dt;
    } else {
      let drain = 0.07;
      if (this.action === 'run') drain += 0.25;
      if (this.mode === 'wall') drain += 0.2;
      this.energy -= drain * dt;
    }
    this.energy = clamp(this.energy, 0, 100);
    this.happiness = clamp(this.happiness + (60 - this.happiness) * 0.004 * dt, 0, 100);
    this.moodTimer -= dt;
    if (this.moodTimer <= 0) {
      this.moodTimer = rand(25, 50);
      this.emit('mood', { energy: this.energy, happiness: this.happiness });
    }
  }

  update(dt) {
    if (this.x === null || !this.world.ready) return;
    this.awake += dt;
    this.updateMood(dt);
    if (this.mode !== 'held') this.tilt *= Math.exp(-8 * dt);

    if (this.mode === 'held') {
      this.updateHeld(dt);
    } else if (this.mode === 'ground') {
      if (this.action === 'land' || this.action === 'dizzy') {
        this.validateGround();
        this.timer -= dt;
        if (this.timer <= 0) {
          if (this.paused) this.startGround('idle');
          else if (this.action === 'dizzy') this.chooseNext();
          else this.startGround(chance(0.6) ? 'walk' : 'idle');
        }
      } else {
        this.updateGround(dt);
      }
    } else if (this.mode === 'wall') {
      this.updateWall(dt);
    } else {
      this.updateAir(dt);
    }
  }
}

// Speech-bubble emoticons (GIFs from /emoticons) shown above the pet's head.

const CATEGORIES = {
  surprise: ['!', 'omg', 'ani_o', 'wah'],
  help: ['help', 'wah'],
  dizzy: ['ani_slur', 'ani_x', 'swt'],
  happy: ['ani_heh', 'ho', 'ok', 'no1'],
  love: ['lv', 'ani_awsm', 'kis2', 'ani_kis'],
  shy: ['ani_shy'],
  sleepy: ['ani_yawn'],
  sleeping: ['dotdotdot'],
  thinking: ['hmm', 'questionmark', 'eyes'],
  angry: ['ani_an', 'ani_arg', 'ani_bzz', 'pif'],
  sad: ['sob', 'ani_meh', 'sry'],
  effort: ['swt', 'go'],
  go: ['go', 'ok'],
  thanks: ['ani_thx'],
  hungry: ['ani_rice'],
  rps: ['gawi', 'bawi', 'bo'],
};

// Pet event -> [category, probability]; probability 1 means always (ignores cooldown).
const REACTIONS = {
  grab: ['surprise', 1],
  heldLong: ['help', 1],
  hardLand: ['dizzy', 1],
  bump: ['dizzy', 0.6],
  climb: ['effort', 0.35],
  climbTop: ['happy', 0.4],
  sleep: ['sleepy', 1],
  emote: ['happy', 0.45],
  pause: ['thinking', 0.8],
  resume: ['go', 1],
  restart: ['surprise', 1],
  idle: ['thinking', 0.12],
  edge: ['thinking', 0.2],
  hop: ['go', 0.3],
  sit: ['happy', 0.15],
};

const pick = (list) => list[Math.floor(Math.random() * list.length)];

export class Emoticons {
  constructor(list, cfg) {
    this.images = new Map(list.map((e) => [e.name, e.data]));
    this.cfg = cfg;
    this.el = document.createElement('img');
    this.el.className = 'emoticon';
    this.el.draggable = false;
    document.body.appendChild(this.el);
    this.visible = 0;
    this.cooldown = 0;
    this.sleepTimer = 4;
    this.scale = 2;
  }

  setSize(P) {
    this.scale = Math.max(1, Math.round((P / 110) * 2 * 2) / 2);
  }

  show(category, force = false) {
    if (this.cfg.emoticons === false) return;
    if (!force && (this.cooldown > 0 || this.visible > 0)) return;
    const names = (CATEGORIES[category] || []).filter((n) => this.images.has(n));
    if (!names.length) return;
    const img = this.el;
    img.onload = () => {
      img.style.width = img.naturalWidth * this.scale + 'px';
      img.style.height = img.naturalHeight * this.scale + 'px';
    };
    img.src = this.images.get(pick(names));
    img.classList.remove('pop');
    void img.offsetWidth;
    img.classList.add('pop');
    this.visible = category === 'sleeping' ? 3 : 2.6;
    this.cooldown = this.visible + 3;
  }

  maybe(category, p) {
    const rate = this.cfg.emoticonRate ?? 1;
    if (p >= 1) this.show(category, true);
    else if (Math.random() < p * rate) this.show(category);
  }

  react(type, data) {
    switch (type) {
      case 'release':
        if (data.speed > 12) this.show('surprise', true);
        return;
      case 'land':
        if (data.thrown) this.maybe(Math.random() < 0.5 ? 'happy' : 'thanks', 0.5);
        return;
      case 'wake':
        if (data.startled) this.show('surprise', true);
        else this.maybe(Math.random() < 0.5 ? 'sleepy' : 'happy', 0.6);
        return;
      case 'pet':
        this.show(Math.random() < 0.3 ? 'shy' : 'love', true);
        return;
      case 'emote':
        this.maybe(Math.random() < 0.15 ? 'rps' : Math.random() < 0.5 ? 'love' : 'happy', 0.45);
        return;
      case 'mood': {
        const { energy: e, happiness: h } = data;
        if (e < 25) this.maybe('sleepy', 0.8);
        else if (h < 15) this.maybe('angry', 0.6);
        else if (h < 30) this.maybe('sad', 0.6);
        else if (e < 35) this.maybe(Math.random() < 0.5 ? 'hungry' : 'effort', 0.5);
        else if (h > 85) this.maybe('love', 0.5);
        else if (h > 70) this.maybe('happy', 0.3);
        return;
      }
    }
    const r = REACTIONS[type];
    if (r) this.maybe(r[0], r[1]);
  }

  // head: screen position just above the pet's head.
  update(dt, head, sleeping, hidden) {
    this.cooldown -= dt;
    if (sleeping) {
      this.sleepTimer -= dt;
      if (this.sleepTimer <= 0) {
        this.sleepTimer = 6 + Math.random() * 4;
        this.show('sleeping');
      }
    } else {
      this.sleepTimer = 4;
    }
    if (this.visible > 0) {
      this.visible -= dt;
      if (this.visible <= 0) this.el.classList.remove('pop');
    }
    const img = this.el;
    img.style.display = this.visible > 0 && !hidden && this.cfg.emoticons !== false ? 'block' : 'none';
    if (img.style.display === 'block') {
      const w = img.offsetWidth;
      const h = img.offsetHeight;
      img.style.transform = `translate(${Math.round(head.x - w / 2)}px, ${Math.round(head.y - h)}px)`;
    }
  }
}

