import { PetView } from './view.js';

// Tiny DOM builder: h('div.a.b', {onclick, style...}, children...)
function h(tag, props = {}, ...children) {
  const [name, ...classes] = tag.split('.');
  const el = document.createElement(name || 'div');
  if (classes.length) el.className = classes.join(' ');
  for (const [k, v] of Object.entries(props || {})) {
    if (v === undefined || v === null || v === false) continue;
    if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
    else if (k === 'style') Object.assign(el.style, v);
    else if (k in el && typeof v !== 'string') el[k] = v;
    else el.setAttribute(k, v === true ? '' : v);
  }
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    el.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

const ACTION_LABELS = {
  idle: 'Parada', walk: 'Andando', run: 'Correndo', sit: 'Sentada', sleep: 'Dormindo', emote: 'Brincando',
  climbUp: 'Escalando', climbDown: 'Descendo', climbRest: 'Descansando na parede', jumpGrab: 'Pulando',
  fall: 'Caindo', land: 'Aterrissando', held: 'Sendo carregada', dizzy: 'Tonta',
};

function bar(label, value, cls) {
  return h('div.bar', {}, h('span', {}, label), h('div.track', {}, h(`div.fill.${cls}`, { style: { width: `${Math.round(value)}%` } })));
}

function slider({ label, min, max, step, value, format, oninput, onchange }) {
  const out = h('span.value', {}, format(value));
  const input = h('input', { type: 'range', min, max, step, value });
  input.addEventListener('input', () => {
    out.textContent = format(+input.value);
    oninput?.(+input.value);
  });
  input.addEventListener('change', () => onchange?.(+input.value));
  return h('label.row.slider', {}, h('span.label', {}, label), input, out);
}

function toggle({ label, value, onchange }) {
  const input = h('input', { type: 'checkbox', checked: !!value, onchange: () => onchange(input.checked) });
  return h('label.row.toggle', {}, h('span.label', {}, label), input, h('span.switch'));
}

// ---------------------------------------------------------------- context menu

export class Menu {
  constructor(app) {
    this.app = app;
    this.el = null;
    this.category = 'controle';
    this.expanded = null;
  }

  get open() {
    return !!this.el;
  }

  show(x, y) {
    this.close();
    this.backdrop = h('div.backdrop', {
      onpointerdown: (e) => e.target === this.backdrop && this.close(),
      oncontextmenu: (e) => {
        e.preventDefault();
        if (e.target === this.backdrop) this.close();
      },
    });
    this.el = h('div.menu', { onpointerdown: (e) => e.stopPropagation() });
    this.backdrop.append(this.el);
    document.body.append(this.backdrop);
    this.render();
    const r = this.el.getBoundingClientRect();
    const left = Math.min(Math.max(8, x + 6), innerWidth - r.width - 8);
    const top = Math.min(Math.max(8, y - r.height / 2), innerHeight - r.height - 8);
    this.el.style.left = left + 'px';
    this.el.style.top = top + 'px';
    this.app.uiChanged();
  }

  close() {
    if (!this.el) return;
    this.backdrop.remove();
    this.el = null;
    this.expanded = null;
    this.app.uiChanged();
  }

  select(category) {
    this.category = category;
    this.expanded = null;
    this.render();
  }

  render() {
    if (!this.el) return;
    const { app } = this;
    const pet = app.pet;
    const cats = [
      ['controle', '▶', 'Controle'],
      ['modelo', '◆', 'Modelo'],
      ['opcoes', '⚙', 'Opções'],
    ];
    const state = pet.paused ? 'Pausada' : ACTION_LABELS[pet.action] || '—';
    this.el.replaceChildren(
      h('div.menu-head', {},
        h('img.avatar', { src: app.avatar, draggable: false }),
        h('div.who', {}, h('div.name', {}, app.config.name || 'Pet'), h('div.state', {}, state)),
        h('div.bars', {}, bar('Energia', pet.energy, 'energy'), bar('Humor', pet.happiness, 'mood')),
      ),
      h('div.cats', {}, cats.map(([id, icon, label]) =>
        h(`button.cat${this.category === id ? '.active' : ''}`, { onclick: () => this.select(id) }, h('span.icon', {}, icon), label))),
      h('div.panel', {}, this[this.category]()),
      h('div.menu-foot', {},
        h('span.hint', {}, 'Clique e segure para carregar'),
        h('button.link', { onclick: () => app.quit() }, 'Sair')),
    );
  }

  tile(icon, label, hint, onclick, { disabled = false, active = false } = {}) {
    return h(`button.tile${active ? '.active' : ''}`, { onclick, disabled }, h('span.icon', {}, icon), h('span.label', {}, label), hint && h('span.hint', {}, hint));
  }

  controle() {
    const { app } = this;
    const paused = app.pet.paused;
    return h('div.grid', {},
      this.tile('⏸', 'Parar', 'Fica parada no lugar', () => { app.pause(); this.render(); }, { disabled: paused }),
      this.tile('▶', 'Continuar', 'Volta a passear', () => { app.resume(); this.render(); }, { disabled: !paused }),
      this.tile('⟲', 'Começar', 'Recomeça do topo da tela', () => { app.restart(); this.close(); }),
      this.tile('⚙', 'Opções', 'Tamanho, velocidade…', () => this.select('opcoes')),
    );
  }

  modelo() {
    const { app } = this;
    const exp = this.expanded;
    const toggleRow = (id) => { this.expanded = exp === id ? null : id; this.render(); };
    const grid = h('div.grid', {},
      this.tile('⤓', 'Importar modelo', 'Yes Steve Model', () => { this.close(); app.openImport(); }),
      this.tile('⇕', 'Ajustar tamanho', `${app.config.petHeight}px`, () => toggleRow('size'), { active: exp === 'size' }),
      this.tile('✎', 'Mudar nome', app.config.name || 'Pet', () => toggleRow('name'), { active: exp === 'name' }),
      h('div.tile.info', {},
        h('span.icon', {}, '▦'),
        h('span.label', {}, 'Modelo atual'),
        h('span.hint', {}, `${app.config.modelDir}`),
        h('span.hint', {}, `${app.view.animator.clips.size} animações`)),
    );
    let extra = null;
    if (exp === 'size') extra = this.sizeSlider();
    if (exp === 'name') {
      const input = h('input.text', { value: app.config.name || '', maxlength: 24, placeholder: 'Nome do pet' });
      const save = () => { app.setName(input.value.trim() || 'Pet'); this.expanded = null; this.render(); };
      input.addEventListener('keydown', (e) => e.key === 'Enter' && save());
      extra = h('div.row.name-row', {}, input, h('button.primary', { onclick: save }, 'Salvar'));
      setTimeout(() => { app.focus(); input.focus(); input.select(); }, 0);
    }
    return [grid, extra && h('div.expand', {}, extra)];
  }

  sizeSlider() {
    const { app } = this;
    return slider({
      label: 'Tamanho', min: 50, max: 300, step: 5, value: app.config.petHeight, format: (v) => `${v}px`,
      oninput: (v) => app.setSize(v),
      onchange: () => this.render(),
    });
  }

  opcoes() {
    const { app } = this;
    const c = app.config;
    return h('div.rows', {},
      this.sizeSlider(),
      slider({ label: 'Velocidade', min: 0.4, max: 2.5, step: 0.1, value: c.speedScale ?? 1, format: (v) => `${v.toFixed(1)}×`,
        oninput: (v) => app.setOption('speedScale', v) }),
      slider({ label: 'Escalar janelas', min: 0, max: 1, step: 0.05, value: c.climbChance, format: (v) => `${Math.round(v * 100)}%`,
        oninput: (v) => app.setOption('climbChance', v) }),
      toggle({ label: 'Emoticons', value: c.emoticons !== false, onchange: (v) => app.setOption('emoticons', v) }),
      slider({ label: 'Frequência', min: 0.2, max: 3, step: 0.1, value: c.emoticonRate ?? 1, format: (v) => `${v.toFixed(1)}×`,
        oninput: (v) => app.setOption('emoticonRate', v) }),
      toggle({ label: 'Modo debug', value: !!c.debug, onchange: (v) => app.setOption('debug', v) }),
    );
  }
}

// ---------------------------------------------------------------- import dialog

const PREVIEW_POSES = { sleep: 'lie', climb: 'climb', climbing: 'climb', sit: 'sit' };
const REQUIRED = ['idle', 'walk', 'run', 'climb', 'climbing', 'sit', 'sleep', 'jump'];
const KIND_LABELS = { folder: 'Pasta', zip: 'Arquivo .zip' };

export class ImportDialog {
  constructor(app) {
    this.app = app;
    this.el = null;
    this.view = null;
  }

  get open() {
    return !!this.el;
  }

  show() {
    this.close();
    this.el = h('div.backdrop.dim', { oncontextmenu: (e) => e.preventDefault() });
    this.modal = h('div.modal');
    this.el.append(this.modal);
    document.body.append(this.el);
    this.app.uiChanged();
    this.app.focus();
    this.stepPick();
    window.addEventListener('keydown', (this.onKey = (e) => e.key === 'Escape' && !this.busy && this.close()));
  }

  close() {
    if (!this.el) return;
    this.disposeView();
    window.removeEventListener('keydown', this.onKey);
    this.el.remove();
    this.el = null;
    this.app.uiChanged();
  }

  disposeView() {
    cancelAnimationFrame(this.raf);
    this.view?.dispose();
    this.view = null;
  }

  frame(title, body, footer) {
    this.modal.replaceChildren(
      h('div.modal-head', {}, h('span.title', {}, title), h('button.close', { onclick: () => !this.busy && this.close() }, '✕')),
      h('div.modal-body', {}, body),
      footer && h('div.modal-foot', {}, footer),
    );
  }

  stepPick(error) {
    this.disposeView();
    const pick = async (folder) => {
      const path = await window.petAPI.pickModelSource(folder);
      if (path) this.inspect(path);
    };
    this.frame('Importar modelo Yes Steve Model', h('div.pick', {},
      h('div.grid', {},
        h('button.tile.big', { onclick: () => pick(true) }, h('span.icon', {}, '📁'), h('span.label', {}, 'Pasta do modelo'),
          h('span.hint', {}, 'Pasta exportada com main.json, animações e textura')),
        h('button.tile.big', { onclick: () => pick(false) }, h('span.icon', {}, '🗜'), h('span.label', {}, 'Arquivo .zip / .ysm'),
          h('span.hint', {}, '.zip da pasta exportada')),
      ),
      error && h('div.error', {}, error),
      h('p.note', {}, 'Arquivos .ysm são criptografados pelo mod. Use a versão exportada (pasta ou .zip) do modelo.'),
    ), [h('button', { onclick: () => this.close() }, 'Cancelar')]);
  }

  async inspect(path) {
    this.frame('Importar modelo Yes Steve Model', h('div.loading', {}, h('div.spinner'), 'Lendo modelo…'));
    try {
      const { info, model } = await window.petAPI.inspectModel(path);
      if (!this.el) return;
      await this.stepPreview(path, info, model);
    } catch (e) {
      if (this.el) this.stepPick(String(e));
    }
  }

  async stepPreview(path, info, model) {
    const app = this.app;
    const allNames = info.animationFiles.flatMap((f) => f.names);
    const state = { name: info.name, texture: info.textures[0]?.name, size: app.config.petHeight, anim: allNames.includes('idle') ? 'idle' : allNames[0], facing: 'front' };

    const canvas = h('canvas.stage-canvas');
    const stage = h('div.stage', {}, canvas);
    const animLabel = h('div.anim-name', {}, state.anim || '—');

    const play = (name) => {
      if (!this.view || !name) return;
      state.anim = name;
      animLabel.textContent = name;
      const pose = PREVIEW_POSES[name] || 'stand';
      const facing = pose === 'lie' && state.facing === 'front' ? 'right' : state.facing;
      this.view.setPose(pose);
      this.view.setFacing(facing);
      this.view.play(name, { restart: true, fade: 0 });
      this.view.reanchor();
      for (const c of chips.children) c.classList.toggle('active', c.dataset.name === name);
    };

    const buildView = async () => {
      this.disposeView();
      const tex = info.textures.find((t) => t.name === state.texture) || info.textures[0];
      this.view = await PetView.create({ ...model, texture: tex.data }, 150, canvas);
      play(state.anim);
      let last = performance.now();
      const loop = (now) => {
        if (!this.view) return;
        this.view.update(Math.min(0.05, (now - last) / 1000));
        last = now;
        this.raf = requestAnimationFrame(loop);
      };
      this.raf = requestAnimationFrame(loop);
    };

    const facingBtns = h('div.seg', {}, [['front', 'Frente'], ['right', 'Direita'], ['left', 'Esquerda'], ['back', 'Costas']].map(([id, label]) =>
      h(`button${id === state.facing ? '.active' : ''}`, {
        onclick: (e) => {
          state.facing = id;
          for (const b of facingBtns.children) b.classList.toggle('active', b === e.currentTarget);
          play(state.anim);
        },
      }, label)));

    const chips = h('div.chips', {}, allNames.map((n) => h(`button.chip${REQUIRED.includes(n) ? '.core' : ''}`, { 'data-name': n, onclick: () => play(n) }, n)));

    const nameInput = h('input.text', { value: state.name, maxlength: 24, oninput: () => (state.name = nameInput.value) });
    const textures = h('div.textures', {}, info.textures.map((t) =>
      h(`button.texture${t.name === state.texture ? '.active' : ''}`, {
        title: `${t.name} (${t.width}×${t.height})`,
        onclick: async (e) => {
          state.texture = t.name;
          for (const b of textures.children) b.classList.toggle('active', b === e.currentTarget);
          await buildView();
        },
      }, h('img', { src: t.data, draggable: false }), h('span', {}, t.name))));

    const missing = REQUIRED.filter((n) => !allNames.includes(n));
    const [tw, th] = info.textureUnits || [];
    const facts = [
      ['Origem', `${KIND_LABELS[info.kind] || info.kind}`],
      ['Geometria', `${info.geometryFile}${tw ? ` · UV ${tw}×${th}` : ''}`],
      ['Ossos', info.bones],
      ['Cubos', info.cubes],
      ['Animações', `${info.animationCount} em ${info.animationFiles.length} arquivo(s)`],
      ...info.animationFiles.map((f) => [`  ${f.file}`, `${f.names.length}`]),
      ['Texturas', info.textures.length],
      info.authors.length && ['Autores', info.authors.join(', ')],
      ['Compatível', missing.length ? `faltam: ${missing.join(', ')}` : 'todas as animações do pet ✓'],
    ].filter(Boolean);

    const body = h('div.import', {},
      h('div.left', {}, stage, animLabel, facingBtns),
      h('div.right', {},
        h('label.row.field', {}, h('span.label', {}, 'Nome'), nameInput),
        slider({ label: 'Tamanho', min: 50, max: 300, step: 5, value: state.size, format: (v) => `${v}px`, oninput: (v) => (state.size = v) }),
        info.textures.length > 1 && h('div.field-block', {}, h('span.label', {}, 'Textura'), textures),
        h('dl.facts', {}, facts.map(([k, v]) => [h('dt', {}, k), h(`dd${k === 'Compatível' && missing.length ? '.warn' : ''}`, {}, String(v))])),
        h('div.field-block', {}, h('span.label', {}, `Animações (${info.animationCount})`), chips),
      ),
    );

    const importBtn = h('button.primary', {
      onclick: async () => {
        this.busy = true;
        importBtn.disabled = true;
        importBtn.textContent = 'Importando…';
        try {
          await window.petAPI.importModel({ path, name: state.name.trim() || info.name, texture: state.texture, petHeight: state.size });
          location.reload();
        } catch (e) {
          this.busy = false;
          importBtn.disabled = false;
          importBtn.textContent = 'Importar';
          errorBox.textContent = String(e);
          errorBox.style.display = 'block';
        }
      },
    }, 'Importar');
    const errorBox = h('div.error', { style: { display: 'none' } });

    this.frame(`Importar: ${info.name}`, [body, errorBox], [
      h('button', { onclick: () => this.stepPick() }, 'Voltar'),
      h('span.grow'),
      h('button', { onclick: () => this.close() }, 'Cancelar'),
      importBtn,
    ]);
    await buildView();
  }
}

html, body { margin: 0; padding: 0; overflow: hidden; background: transparent; width: 100%; height: 100%; }
body { font: 13px/1.35 'Segoe UI', system-ui, sans-serif; color: #eef0f6; user-select: none; }
#pet { position: absolute; left: 0; top: 0; will-change: transform; pointer-events: none; }
#debug { position: absolute; left: 0; top: 0; pointer-events: none; }
body.hover { cursor: grab; }
body.grabbing, body.grabbing * { cursor: grabbing !important; }

:root {
  --bg: rgba(24, 24, 34, 0.94);
  --panel: rgba(255, 255, 255, 0.05);
  --panel-hover: rgba(255, 255, 255, 0.1);
  --line: rgba(255, 255, 255, 0.09);
  --muted: #9aa0b4;
  --accent: #e2475f;
  --accent-soft: rgba(226, 71, 95, 0.18);
}

/* ---------- emoticon ---------- */
.emoticon { position: absolute; left: 0; top: 0; display: none; pointer-events: none; will-change: transform; }
.emoticon img { display: block; image-rendering: pixelated; transform-origin: 50% 100%; }
.emoticon img.pop { animation: pop 0.28s cubic-bezier(0.3, 1.6, 0.5, 1); }
@keyframes pop { from { transform: scale(0.2); opacity: 0; } to { transform: scale(1); opacity: 1; } }

/* ---------- shared ---------- */
.backdrop { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.001); z-index: 10; }
.backdrop.dim { background: rgba(8, 8, 14, 0.45); display: grid; place-items: center; animation: fade 0.15s; }
@keyframes fade { from { opacity: 0; } }
button {
  font: inherit; color: inherit; background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 6px 12px; cursor: pointer; transition: background 0.12s, border-color 0.12s, transform 0.08s;
}
button:hover:not(:disabled) { background: var(--panel-hover); }
button:active:not(:disabled) { transform: scale(0.97); }
button:disabled { opacity: 0.35; cursor: default; }
button.primary { background: var(--accent); border-color: transparent; color: #fff; font-weight: 600; }
button.primary:hover:not(:disabled) { background: #ef5a71; }
button.link { background: none; border: none; color: var(--muted); padding: 2px 6px; }
button.link:hover { color: #fff; background: none; }
input.text {
  font: inherit; color: inherit; background: rgba(0, 0, 0, 0.3); border: 1px solid var(--line); border-radius: 7px;
  padding: 6px 9px; outline: none; min-width: 0; flex: 1; user-select: text;
}
input.text:focus { border-color: var(--accent); }

.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.tile {
  display: grid; grid-template-columns: 30px 1fr; grid-template-rows: auto auto; align-items: center;
  column-gap: 8px; text-align: left; padding: 9px 10px; border-radius: 10px; min-height: 52px;
}
.tile .icon { grid-row: span 3; font-size: 19px; text-align: center; color: var(--accent); }
.tile .label { font-weight: 600; }
.tile .hint { color: var(--muted); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tile.active { border-color: var(--accent); background: var(--accent-soft); }
.tile.info { background: transparent; border-style: dashed; cursor: default; }
.tile.big { grid-template-columns: 1fr; text-align: center; justify-items: center; padding: 22px 14px; row-gap: 4px; }
.tile.big .icon { grid-row: auto; font-size: 34px; }

.row { display: flex; align-items: center; gap: 10px; }
.row .label { color: var(--muted); width: 96px; flex: none; }
.rows { display: grid; gap: 10px; }
.slider input { flex: 1; accent-color: var(--accent); min-width: 0; }
.slider .value { width: 46px; text-align: right; font-variant-numeric: tabular-nums; }
.toggle { cursor: pointer; }
.toggle input { display: none; }
.toggle .switch { margin-left: auto; width: 34px; height: 18px; border-radius: 9px; background: rgba(255, 255, 255, 0.15); position: relative; transition: background 0.15s; }
.toggle .switch::after { content: ''; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: #fff; transition: transform 0.15s; }
.toggle input:checked + .switch { background: var(--accent); }
.toggle input:checked + .switch::after { transform: translateX(16px); }

/* ---------- context menu ---------- */
.menu {
  position: absolute; width: 330px; background: var(--bg); border: 1px solid var(--line); border-radius: 14px;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5); padding: 12px; display: grid; gap: 10px;
  backdrop-filter: blur(12px); animation: menu-in 0.14s ease-out;
}
@keyframes menu-in { from { opacity: 0; transform: translateY(4px) scale(0.98); } }
.menu-head { display: grid; grid-template-columns: 44px 1fr; grid-template-rows: auto auto; column-gap: 10px; row-gap: 8px; align-items: center; }
.avatar { width: 44px; height: 44px; border-radius: 10px; background: rgba(255, 255, 255, 0.06); image-rendering: pixelated; }
.who .name { font-size: 15px; font-weight: 700; }
.who .state { color: var(--muted); font-size: 12px; }
.bars { grid-column: span 2; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.bar { display: grid; gap: 3px; font-size: 11px; color: var(--muted); }
.track { height: 5px; border-radius: 3px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.fill { height: 100%; border-radius: 3px; transition: width 0.3s; }
.fill.energy { background: linear-gradient(90deg, #f0b43c, #7bd35a); }
.fill.mood { background: linear-gradient(90deg, #7a8cff, #ff6f91); }
.cats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; padding: 4px; background: rgba(0, 0, 0, 0.25); border-radius: 10px; }
.cat { border: none; background: transparent; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 4px; }
.cat .icon { color: var(--muted); }
.cat.active { background: var(--accent-soft); color: #fff; }
.cat.active .icon { color: var(--accent); }
.panel { display: grid; gap: 10px; }
.expand { padding: 10px; border-radius: 10px; background: rgba(0, 0, 0, 0.22); }
.menu-foot { display: flex; align-items: center; justify-content: space-between; border-top: 1px solid var(--line); padding-top: 8px; }
.menu-foot .hint { color: var(--muted); font-size: 11px; }

/* ---------- import dialog ---------- */
.modal {
  width: min(780px, calc(100vw - 40px)); max-height: calc(100vh - 40px); display: grid; grid-template-rows: auto 1fr auto;
  background: var(--bg); border: 1px solid var(--line); border-radius: 16px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.55);
  animation: menu-in 0.16s ease-out; overflow: hidden;
}
.modal-head { display: flex; align-items: center; padding: 12px 14px 12px 18px; border-bottom: 1px solid var(--line); }
.modal-head .title { font-size: 15px; font-weight: 700; flex: 1; }
.modal-head .close { border: none; background: none; color: var(--muted); }
.modal-body { padding: 16px 18px; overflow: auto; }
.modal-foot { display: flex; gap: 8px; padding: 12px 18px; border-top: 1px solid var(--line); }
.modal-foot .grow { flex: 1; }
.pick { display: grid; gap: 14px; }
.note { color: var(--muted); font-size: 12px; margin: 0; }
.error { background: rgba(226, 71, 95, 0.14); border: 1px solid rgba(226, 71, 95, 0.4); border-radius: 9px; padding: 9px 11px; color: #ffc3cc; user-select: text; margin-top: 10px; }
.loading { display: grid; justify-items: center; gap: 12px; padding: 50px 0; color: var(--muted); }
.spinner { width: 28px; height: 28px; border-radius: 50%; border: 3px solid var(--line); border-top-color: var(--accent); animation: spin 0.8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.import { display: grid; grid-template-columns: 360px 1fr; gap: 18px; }
.import .left { display: grid; gap: 8px; align-content: start; }
.stage {
  height: 270px; border-radius: 12px; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 80%, #3a3f5c, #1c1e2b 70%);
}
.anim-name { text-align: center; color: var(--muted); font-size: 12px; }
.seg { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; padding: 3px; background: rgba(0, 0, 0, 0.25); border-radius: 9px; }
.seg button { border: none; background: transparent; padding: 5px 2px; }
.seg button.active { background: var(--accent-soft); color: #fff; }
.import .right { display: grid; gap: 12px; align-content: start; min-width: 0; }
.field-block { display: grid; gap: 6px; }
.field-block > .label { color: var(--muted); }
.facts { display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; margin: 0; padding: 10px 12px; border-radius: 10px; background: rgba(0, 0, 0, 0.22); font-size: 12px; }
.facts dt { color: var(--muted); white-space: pre; }
.facts dd { margin: 0; overflow-wrap: anywhere; }
.facts dd.warn { color: #f0b43c; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; max-height: 110px; overflow: auto; }
.chip { padding: 3px 8px; font-size: 11px; border-radius: 12px; }
.chip.core { border-color: rgba(226, 71, 95, 0.45); }
.chip.active { background: var(--accent); border-color: transparent; color: #fff; }
.textures { display: flex; gap: 6px; flex-wrap: wrap; }
.texture { display: grid; justify-items: center; gap: 3px; padding: 5px; font-size: 10px; max-width: 84px; }
.texture img { width: 64px; height: 64px; image-rendering: pixelated; background: rgba(255, 255, 255, 0.06); border-radius: 5px; }
.texture span { max-width: 74px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.texture.active { border-color: var(--accent); background: var(--accent-soft); }

// Exposes the host API (Tauri commands/events) to the rest of the renderer.
const { invoke } = window.__TAURI__.core;
const { listen } = window.__TAURI__.event;

window.petAPI = {
  getConfig: () => invoke('get_config'),
  saveConfig: (patch) => invoke('save_config', { patch }),
  loadModel: () => invoke('load_model'),
  loadEmoticons: () => invoke('load_emoticons'),
  pickModelSource: (folder) => invoke('pick_model_source', { folder }),
  inspectModel: (path) => invoke('inspect_model', { path }),
  importModel: ({ path, name, texture, petHeight }) => invoke('import_model', { path, name, texture, petHeight }),
  setInteractive: (value) => invoke('set_interactive', { value }),
  focusWindow: () => invoke('focus_window'),
  quit: () => invoke('quit'),
  onWorld: (cb) => listen('world', (e) => cb(e.payload)),
  savePreview: (name, dataUrl) => invoke('save_preview', { name, dataUrl }),
  previewDone: () => invoke('preview_done'),
  setTrayIcon: (dataUrl) => invoke('set_tray_icon', { dataUrl }),
  log: (...args) => invoke('log', { msg: args.map(String).join(' ') }),
};

import { PetView } from './view.js';
import { World } from './world.js';
import { Pet } from './behavior.js';
import { Emoticons } from './emoticons.js';
import { Menu, ImportDialog } from './ui.js';

const api = window.petAPI;

function drawDebug(canvas, world, on) {
  canvas.width = on ? world.width : 0;
  canvas.height = on ? world.height : 0;
  if (!on) return;
  const g = canvas.getContext('2d');
  g.lineWidth = 3;
  g.strokeStyle = 'rgba(0,255,90,0.8)';
  for (const s of world.surfaces) {
    g.beginPath();
    g.moveTo(s.x1, s.y - 1.5);
    g.lineTo(s.x2, s.y - 1.5);
    g.stroke();
  }
  g.strokeStyle = 'rgba(255,150,0,0.8)';
  for (const w of world.walls) {
    g.beginPath();
    g.moveTo(w.x, w.y1);
    g.lineTo(w.x, w.y2);
    g.stroke();
  }
}

function portrait(view) {
  const c = document.createElement('canvas');
  const size = 64;
  c.width = c.height = size;
  const r = devicePixelRatio;
  const P = view.petHeight;
  const sx = (view.feetX - P * 0.3) * r;
  const sy = (view.feetY - P * 1.02) * r;
  c.getContext('2d').drawImage(view.canvas, sx, sy, P * 0.6 * r, P * 0.6 * r, 0, 0, size, size);
  return c.toDataURL('image/png');
}

export async function startPet(files, config) {
  const canvas = document.getElementById('pet');
  const debugCanvas = document.getElementById('debug');
  const view = await PetView.create(files, config.petHeight, canvas);
  const world = new World(config.petHeight);
  const pet = new Pet(view, world, config);
  const emoticons = new Emoticons(await api.loadEmoticons().catch(() => []), config);
  emoticons.setSize(config.petHeight);

  view.play('idle', { fade: 0 });
  view.update(0);
  const avatar = portrait(view);
  api.setTrayIcon(avatar);

  // ---------- settings ----------
  let pending = {};
  let saveTimer = 0;
  const save = (patch) => {
    Object.assign(pending, patch);
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => {
      api.saveConfig(pending).catch((e) => api.log('save failed', e));
      pending = {};
    }, 400);
  };

  const app = {
    config,
    pet,
    view,
    avatar,
    pause: () => pet.pause(),
    resume: () => pet.resume(),
    restart: () => pet.restart(),
    quit: () => api.quit(),
    focus: () => api.focusWindow(),
    openImport: () => importDialog.show(),
    uiChanged: () => {
      if (menu.open || importDialog.open) api.focusWindow();
      misses = 99;
      refreshInteractive();
    },
    setSize(P) {
      config.petHeight = P;
      view.resize(P);
      pet.setSize(P);
      emoticons.setSize(P);
      save({ petHeight: P });
    },
    setName(name) {
      config.name = name;
      save({ name });
    },
    setOption(key, value) {
      config[key] = value;
      if (key === 'speedScale') pet.setSize(pet.P);
      if (key === 'debug') drawDebug(debugCanvas, world, value);
      save({ [key]: value });
    },
  };
  const menu = new Menu(app);
  const importDialog = new ImportDialog(app);

  pet.on((type, data) => {
    emoticons.react(type, data);
    if (config.debug) api.log(`event ${type} ${JSON.stringify(data)}`);
  });

  // ---------- mouse interaction ----------
  // The overlay ignores the mouse except while the cursor is over a drawn pixel of the pet
  // (polled from the host, since a click-through window receives no mouse events) or a UI is open.
  const place = { left: 0, top: 0, ox: 0, oy: 0, tilt: 0 };
  let cursor = null;
  let interactive = false;
  let misses = 0;
  let press = null;

  const uiOpen = () => menu.open || importDialog.open;

  const hitPet = (x, y) => {
    if (pet.x === null || canvas.style.visibility === 'hidden') return false;
    let lx = x - place.left;
    let ly = y - place.top;
    if (place.tilt) {
      const c = Math.cos(-place.tilt);
      const s = Math.sin(-place.tilt);
      const dx = lx - place.ox;
      const dy = ly - place.oy;
      lx = place.ox + dx * c - dy * s;
      ly = place.oy + dx * s + dy * c;
    }
    return view.hitTest(lx, ly, 3);
  };

  const setInteractive = (value) => {
    if (value === interactive) return;
    interactive = value;
    api.setInteractive(value);
  };

  function refreshInteractive() {
    if (uiOpen() || press) {
      document.body.classList.remove('hover');
      return setInteractive(true);
    }
    const hit = !!cursor && hitPet(cursor.x, cursor.y);
    document.body.classList.toggle('hover', hit);
    if (hit) {
      misses = 0;
      setInteractive(true);
    } else if (++misses >= 2) {
      setInteractive(false);
    }
  }

  const startGrab = () => {
    if (!press || press.grabbing) return;
    press.grabbing = true;
    pet.grab(press.x, press.y);
    pet.drag(press.lx, press.ly);
    document.body.classList.add('grabbing');
  };

  const endPress = () => {
    if (!press) return;
    clearTimeout(press.timer);
    if (press.grabbing) pet.release();
    else pet.pat();
    press = null;
    document.body.classList.remove('grabbing');
  };

  window.addEventListener('contextmenu', (e) => e.preventDefault());
  window.addEventListener('pointerdown', (e) => {
    if (uiOpen() || press || !hitPet(e.clientX, e.clientY)) return;
    if (e.button === 2) return menu.show(e.clientX, e.clientY);
    if (e.button !== 0) return;
    press = { x: e.clientX, y: e.clientY, lx: e.clientX, ly: e.clientY, grabbing: false };
    press.timer = setTimeout(startGrab, 170);
    document.body.setPointerCapture(e.pointerId);
  });
  window.addEventListener('pointermove', (e) => {
    if (!press) return;
    press.lx = e.clientX;
    press.ly = e.clientY;
    if (!press.grabbing && Math.hypot(press.lx - press.x, press.ly - press.y) > 5) startGrab();
    if (press.grabbing) pet.drag(press.lx, press.ly);
  });
  window.addEventListener('pointerup', endPress);
  window.addEventListener('pointercancel', endPress);
  window.addEventListener('keydown', (e) => e.key === 'Escape' && menu.close());
  window.addEventListener('blur', () => {
    if (menu.open && !importDialog.open) menu.close();
  });

  // ---------- world ----------
  api.onWorld((raw) => {
    const s = devicePixelRatio;
    const data = {
      ...raw,
      width: raw.width / s,
      height: raw.height / s,
      windows: raw.windows.map((w) => ({ ...w, x: w.x / s, y: w.y / s, w: w.w / s, h: w.h / s })),
    };
    cursor = raw.cursor ? { x: raw.cursor[0] / s, y: raw.cursor[1] / s } : null;
    const moved = world.update(data);
    pet.onWorldUpdate(moved);
    canvas.style.visibility = data.fullscreen ? 'hidden' : 'visible';
    if (config.debug) drawDebug(debugCanvas, world, true);
    refreshInteractive();
  });

  if (config.debug) {
    api.log(`view dpr=${devicePixelRatio} inner=${innerWidth}x${innerHeight}`);
    let lastState = '';
    setInterval(() => {
      const f = (v) => (v === null ? '-' : Math.round(v));
      const state = `${pet.mode}/${pet.action}`;
      if (state === lastState) return;
      lastState = state;
      api.log(`${state} x=${f(pet.x)} y=${f(pet.y)} on=${pet.surfaceId ?? pet.wall?.id ?? '-'} E=${f(pet.energy)} H=${f(pet.happiness)}`);
    }, 50);
  }

  // ---------- frame loop ----------
  let last = performance.now();
  const frame = (now) => {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    pet.update(dt);
    view.update(dt);
    if (pet.x !== null) {
      place.left = Math.round(pet.x - view.feetX);
      place.top = Math.round(pet.y - view.feetY);
      place.ox = view.feetX + pet.tiltPivot.x;
      place.oy = view.feetY + pet.tiltPivot.y;
      place.tilt = Math.abs(pet.tilt) < 0.002 ? 0 : pet.tilt;
      canvas.style.transformOrigin = `${place.ox}px ${place.oy}px`;
      canvas.style.transform = `translate(${place.left}px, ${place.top}px) rotate(${place.tilt}rad)`;

      // Point just above the head, rotated with the body while it swings.
      const px = view.bounds.centerX - pet.tiltPivot.x;
      const py = -view.bounds.top - 4 - pet.tiltPivot.y;
      const c = Math.cos(place.tilt);
      const s = Math.sin(place.tilt);
      const head = {
        x: pet.x + pet.tiltPivot.x + px * c - py * s,
        y: pet.y + pet.tiltPivot.y + px * s + py * c,
      };
      emoticons.update(dt, head, pet.mode === 'ground' && pet.action === 'sleep', canvas.style.visibility === 'hidden');
    }
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}

