export const STAT_LABELS = { health: 'Saúde', hunger: 'Fome', mood: 'Humor', energy: 'Energia' };

export const itemById = (id) => ITEMS.find((i) => i.id === id);
export const isEdible = (item) => item && (item.cat === 'comidas' || item.cat === 'bebidas');

export function effectText(effects) {
  return Object.entries(effects)
    .map(([k, v]) => `${v > 0 ? '+' : ''}${v} ${STAT_LABELS[k]}`)
    .join(' · ');
}

export class Game {
  constructor(pet, save) {
    this.pet = pet;
    this.inventory = { ...(save?.inventory || {}) };
    this.listeners = [];
    this.dirty = false;
    setInterval(() => this.persist(), 15000);
    pet.on((type) => {
      if (type === 'death') this.reset();
      else if (['eat', 'slap', 'pet', 'chaseEnd', 'wake'].includes(type)) this.dirty = true;
    });
  }

  static async load() {
    try {
      return (await window.petAPI.loadSave()) || null;
    } catch {
      return null;
    }
  }

  onChange(fn) {
    this.listeners.push(fn);
  }

  changed() {
    this.dirty = true;
    for (const fn of this.listeners) fn();
    this.persist();
  }

  count(id) {
    return this.inventory[id] || 0;
  }

  items(filter = () => true) {
    return Object.entries(this.inventory)
      .filter(([, n]) => n > 0)
      .map(([id, n]) => ({ item: itemById(id), count: n }))
      .filter((e) => e.item && filter(e.item));
  }

  buy(id) {
    if (!itemById(id)) return;
    this.inventory[id] = Math.min(99, this.count(id) + 1);
    this.changed();
  }

  use(id) {
    const item = itemById(id);
    if (!item || !this.count(id) || !isEdible(item)) return false;
    if (!this.pet.feed(item)) return false;
    this.inventory[id]--;
    if (!this.inventory[id]) delete this.inventory[id];
    this.changed();
    return true;
  }

  // Losing the pet wipes all progress.
  reset() {
    this.inventory = {};
    this.changed();
  }

  persist() {
    const stats = this.pet.dead ? { ...FULL_STATS } : { ...this.pet.stats };
    window.petAPI.storeSave({ version: 1, stats, inventory: this.inventory, savedAt: Date.now() }).catch(() => {});
    this.dirty = false;
  }
}

