show(x, y) {
  this.close();
  this.backdrop = h('div.backdrop', {
    onpointerdown: (e) => e.target === this.backdrop && this.close(),
    oncontextmenu: (e) => {
      e.preventDefault();
      if (e.target === this.backdrop) this.close();
    },
  });
  this.el = h('div.menu', { onpointerdown: (e) => e.stopPropagation() });
  this.backdrop.append(this.el);
  document.body.append(this.backdrop);
  this.render();
  this.anchor = { x, y };
  this.place();
  this.ticker = setInterval(() => this.refreshStats(), 500);
  this.app.uiChanged();
}

place() {
  const r = this.el.getBoundingClientRect();
  const { x, y } = this.anchor;
  this.el.style.left = Math.min(Math.max(8, x + 6), innerWidth - r.width - 8) + 'px';
  this.el.style.top = Math.min(Math.max(8, y - r.height / 2), innerHeight - r.height - 8) + 'px';
}

close() {
  if (!this.el) return;
  clearInterval(this.ticker);
  this.backdrop.remove();

input.new_string:
show(x, y) {
  this.close();
  const outside = (e) => e.target === this.backdrop && !this.app.overPet(e.clientX, e.clientY);
  this.backdrop = h('div.backdrop', {
    onpointerdown: (e) => e.button === 0 && outside(e) && this.close(),
    oncontextmenu: (e) => {
      e.preventDefault();
      if (outside(e)) this.close();
    },
  });
  this.el = h('div.menu', {
    onpointerdown: (e) => {
      e.stopPropagation();
      if (e.button === 2 || (e.button === 0 && e.target.closest('.menu-head'))) this.startDrag(e);
    },
    oncontextmenu: (e) => e.preventDefault(),
  });
  wireSounds(this.el, this.app.sound);
  this.backdrop.append(this.el);
  document.body.append(this.backdrop);
  this.manual = null;
  this.render();
  this.anchor = { x, y };
  this.place();
  this.ticker = setInterval(() => this.refreshStats(), 500);
  this.app.uiChanged();
}

// Dragging with the right button anywhere on the menu (or the left one on its header).
startDrag(e) {
  const r = this.el.getBoundingClientRect();
  const ox = e.clientX - r.left;
  const oy = e.clientY - r.top;
  const el = this.el;
  el.classList.add('dragging');
  try {
    el.setPointerCapture(e.pointerId);
  } catch {}
  const move = (ev) => {
    this.manual = { left: ev.clientX - ox, top: ev.clientY - oy };
    this.place();
  };
  const up = () => {
    el.classList.remove('dragging');
    el.removeEventListener('pointermove', move);
    el.removeEventListener('pointerup', up);
    el.removeEventListener('pointercancel', up);
  };
  el.addEventListener('pointermove', move);
  el.addEventListener('pointerup', up);
  el.addEventListener('pointercancel', up);
}

place() {
  const r = this.el.getBoundingClientRect();
  const fit = (v, size, max) => Math.min(Math.max(8, v), max - size - 8);
  if (this.manual) {
    this.el.style.left = fit(this.manual.left, r.width, innerWidth) + 'px';
    this.el.style.top = fit(this.manual.top, r.height, innerHeight) + 'px';
    return;
  }
  const { x, y } = this.anchor;
  this.el.style.left = fit(x + 6, r.width, innerWidth) + 'px';
  this.el.style.top = fit(y - r.height / 2, r.height, innerHeight) + 'px';
}

close() {
  if (!this.el) return;
  this.app.sound?.play('cancel', { volume: 0.4 });
  clearInterval(this.ticker);
  this.backdrop.remove();

