tone8(f0, f1, dur, type = 'square', vol = 0.1) {
  if (!this.enabled) return;
  this.tone(type, f0, f1, this.ctx.currentTime + 0.005, dur, vol);
}

bell(strength = 1) {
  if (!this.enabled) return;
  const t = this.ctx.currentTime + 0.005;
  const v = 0.06 + 0.08 * Math.min(1, strength);
  this.tone('square', 1568, 1560, t, 0.25, v);
  this.tone('triangle', 2350, 2340, t, 0.35, v * 0.8);
}

// Animal-crossing style babble: a few random square blips.
voice(syllables = 4) {
  if (!this.enabled) return;
  const pitch = { grave: 0.6, normal: 1, agudo: 1.6 }[this.cfg.voicePitch] ?? 1;
  const vol = (this.cfg.voiceVolume ?? 0.7) * 0.18;
  let t = this.ctx.currentTime + 0.01;
  for (let i = 0; i < syllables; i++) {
    const f = rand(320, 520) * pitch;
    this.tone('square', f, f * rand(0.8, 1.25), t, 0.07, vol);
    t += rand(0.08, 0.12);
  }
}

