export const STAT_LABELS = { health: 'Saúde', hunger: 'Fome', mood: 'Humor', energy: 'Energia' };

export const itemById = (id) => ITEMS.find((i) => i.id === id);
export const isEdible = (item) => item && (item.cat === 'comidas' || item.cat === 'bebidas');
export const isConsumable = (item) => isEdible(item) || item?.cat === 'medicina';

export function effectText(item) {
  const effects = item.effects || item;
  const parts = Object.entries(effects).map(([k, v]) => `${v > 0 ? '+' : ''}${v} ${STAT_LABELS[k]}`);
  if (item.buff) parts.push(`${BUFF_LABELS[item.buff[0]]} por ${item.buff[1] / 60} min`);
  if (item.toy) parts.push('Coloque na área de trabalho');
  if (item.cart) parts.push('Vai para a bolsa do Game Boy');
  return parts.join(' · ');
}

const newProfile = () => ({
  born: Date.now(), consumed: {}, pats: 0, slaps: 0, chases: 0, chaseWins: 0, escapes: 0,
  gamesPlayed: 0, coinsEarned: 0, toysBought: 0, requestsDone: 0,
});

export class Game {
  constructor(pet, save) {
    this.pet = pet;
    this.listeners = [];
    this.dirty = false;
    this.load(save);
    setInterval(() => this.persist(), 15000);
    // A coin per minute while the pet is alive.
    setInterval(() => !pet.dead && this.earn(1), 60000);
    pet.on((type, data) => {
      const p = this.profile;
      if (type === 'death') return this.reset();
      if (type === 'pet') p.pats++;
      if (type === 'slap') p.slaps++;
      if (type === 'chaseStart') p.chases++;
      if (type === 'chaseEnd' && data.caught) {
        p.chaseWins++;
        this.earn(15);
      }
      if (type === 'qteEscape') p.escapes++;
      if (type === 'requestDone') {
        p.requestsDone++;
        this.earn(10);
      }
      if (type === 'ate') p.consumed[data.item.id] = (p.consumed[data.item.id] || 0) + 1;
      if (['eat', 'slap', 'pet', 'chaseEnd', 'wake'].includes(type)) this.dirty = true;
    });
  }

  load(save) {
    this.inventory = { ...(save?.inventory || {}) };
    this.coins = save?.coins ?? 300;
    this.profile = { ...newProfile(), ...(save?.profile || {}) };
    // toys: { id: { uses, maxUses, broken, placed, x } }
    this.toys = { ...(save?.toys || {}) };
    this.cartridges = save?.cartridges || ['tetris'];
    this.cartridge = save?.cartridge || 'tetris';
    this.bag = !!save?.bag;
    this.pet.buffs = { ...(save?.buffs || {}) };
  }

  static async load() {
    try {
      return (await window.petAPI.loadSave()) || null;
    } catch {
      return null;
    }
  }

  onChange(fn) {
    this.listeners.push(fn);
  }

  changed() {
    this.dirty = true;
    for (const fn of this.listeners) fn();
    this.persist();
  }

  earn(n) {
    this.coins += n;
    this.profile.coinsEarned += n;
    this.changed();
  }

  count(id) {
    return this.inventory[id] || 0;
  }

  items(filter = () => true) {
    return Object.entries(this.inventory)
      .filter(([, n]) => n > 0)
      .map(([id, n]) => ({ item: itemById(id), count: n }))
      .filter((e) => e.item && filter(e.item));
  }

  // Whether the item is listed in the shop right now.
  available(item) {
    if (item.legacy) return false;
    if (item.cart) return !!this.toys.gameboy && !this.cartridges.includes(item.cart);
    if (item.toy) {
      const t = this.toys[item.id];
      return !t || t.broken || (!t.placed && !this.count(item.id) && false) || !t.placed;
    }
    return true;
  }

  canBuy(item, n = 1) {
    return (item.price || 0) * n <= this.coins;
  }

  // Returns the bought item (for the purchase reaction) or null.
  buy(id, n = 1) {
    const item = itemById(id);
    if (!item || !this.canBuy(item, n)) return null;
    this.coins -= (item.price || 0) * n;
    if (item.cart) {
      this.cartridges.push(item.cart);
      this.bag = true;
    } else if (item.toy) {
      this.toys[id] = { uses: 0, maxUses: 20 + Math.floor(Math.random() * 31), broken: false, placed: false, x: null };
      this.inventory[id] = 1;
      this.profile.toysBought++;
    } else {
      this.inventory[id] = Math.min(99, this.count(id) + n);
    }
    this.changed();
    this.pet.bought(item);
    return item;
  }

  use(id) {
    const item = itemById(id);
    if (!item || !this.count(id) || !isConsumable(item)) return false;
    if (item.cat === 'medicina') {
      if (this.pet.dead) return false;
      this.pet.medicate(item);
      this.profile.consumed[id] = (this.profile.consumed[id] || 0) + 1;
    } else if (!this.pet.feed(item)) return false;
    this.take(id);
    return true;
  }

  take(id) {
    this.inventory[id]--;
    if (!this.inventory[id]) delete this.inventory[id];
    this.changed();
  }

  // ---------- toys ----------

  placeToy(id, x) {
    const t = this.toys[id];
    if (!t || t.placed) return false;
    t.placed = true;
    t.x = x;
    if (this.count(id)) this.take(id);
    else this.changed();
    return true;
  }

  pickUpToy(id) {
    const t = this.toys[id];
    if (!t?.placed) return;
    t.placed = false;
    this.inventory[id] = 1;
    this.changed();
  }

  // One play session; returns true when the toy broke.
  wearToy(id) {
    const t = this.toys[id];
    if (!t || t.broken) return false;
    t.uses++;
    if (id === 'gameboy') this.profile.gamesPlayed++;
    if (t.uses >= t.maxUses) t.broken = true;
    this.changed();
    return t.broken;
  }

  repairCost(id) {
    return Math.ceil((itemById(id)?.price || 0) / 2);
  }

  repairToy(id) {
    const t = this.toys[id];
    const cost = this.repairCost(id);
    if (!t?.broken || this.coins < cost) return false;
    this.coins -= cost;
    Object.assign(t, { broken: false, uses: 0, maxUses: 20 + Math.floor(Math.random() * 31) });
    this.changed();
    return true;
  }

  difficultyScale() {
    return 1 / Math.sqrt(DIFFICULTIES[this.pet.cfg.difficulty] ?? 1);
  }

  // ---------- save ----------

  // Losing the pet (or deleting the save) wipes all progress.
  reset() {
    this.load(null);
    this.changed();
  }

  persist() {
    const stats = this.pet.dead ? { ...FULL_STATS } : { ...this.pet.stats };
    window.petAPI.storeSave({
      version: 2, stats, inventory: this.inventory, coins: this.coins, profile: this.profile, toys: this.toys,
      cartridges: this.cartridges, cartridge: this.cartridge, bag: this.bag, buffs: this.pet.buffs, savedAt: Date.now(),
    }).catch(() => {});
    this.dirty = false;
  }
}

