// ---------- requests (when unhappy) ----------

// kind: 'food' | 'drink' | 'pat' | 'play'; id: the exact item wanted, if any.
fulfill(kind, id) {
  const r = this.request;
  if (!r || r.kind !== kind || (r.id && id && r.id !== id)) return;
  this.request = null;
  this.adjust({ mood: 12 });
  this.emit('requestDone', r);
}

updateRequest(dt) {
  if (this.request) {
    this.request.t -= dt;
    if (this.request.t <= 0) {
      this.request = null;
      this.emit('requestEnd');
    }
    return;
  }
  if (this.stats.mood >= 60 || this.activity || this.chase) return;
  this.requestTimer -= dt;
  if (this.requestTimer > 0) return;
  this.requestTimer = rand(60, 120);
  const kind = pickWeighted({ food: 3, drink: 2, pat: 2, play: 2 });
  const item = kind === 'food' || kind === 'drink' ? this.requestPool?.(kind === 'food' ? 'comidas' : 'bebidas') : null;
  this.request = { kind, id: item?.id, name: item?.name, img: item?.img, t: 45 };
  this.emit('request', this.request);
}

// ---------- walking to things, toys ----------

goTo(x, cb) {
  if (this.dead || this.chase || this.mode !== 'ground' || ['eat', 'land', 'dizzy', 'hurt'].includes(this.action)) return false;
  const s = this.validateGround();
  if (!s || x < s.x1 || x > s.x2) return false;
  this.paused = false;
  this.action = 'goto';
  this.goal = { x, cb, t: 15 };
  this.dir = x >= this.x ? 1 : -1;
  this.anim('walk', { facing: this.side() });
  return true;
}

// opts: { id, dur, gain, hold (img), holdFrom (s), wobble, anim, pose, facing, onEnd }
playToy(opts) {
  this.toyPlay = { holdFrom: 0, wobble: 0, ...opts, t: 0 };
  this.action = 'toy';
  this.timer = opts.dur;
  this.anim(opts.anim || 'idle', { pose: opts.pose || 'stand', facing: opts.facing || 'front' });
  this.emit('toyStart', { id: opts.id });
}

endToy(interrupted) {
  const tp = this.toyPlay;
  if (!tp) return;
  this.toyPlay = null;
  if (Math.abs(this.tilt) > 0) this.tilt = 0;
  tp.onEnd?.(interrupted);
  this.emit('toyEnd', { id: tp.id, interrupted });
}

// Curious about a new item: walks to it, looks, picks it up and examines it.
inspect(x, img, done) {
  const start = () => this.playToy({ id: 'inspect', dur: 3.8, hold: img, holdFrom: 1.1, wobble: 0.05, onEnd: () => done?.() });
  if (this.goTo(x, start)) return;
  if (this.mode === 'ground' && !this.chase && !this.eating && !this.dead) start();
  else done?.();
}

updateToy(dt) {
  const tp = this.toyPlay;
  tp.t += dt;
  const k = tp.scale ?? 1;
  const delta = {};
  for (const [stat, v] of Object.entries(tp.gain || {})) delta[stat] = v * k * dt;
  this.adjust(delta);
  if (tp.wobble && tp.t >= tp.holdFrom) {
    this.tilt = Math.sin(tp.t * 8) * tp.wobble;
    this.tiltPivot = { x: 0, y: 0 };
  }
  this.timer -= dt;
  if (this.timer <= 0) {
    this.endToy(false);
    this.chooseNext();
  }
}

// ---------- Jam / Assistir ----------

startActivity(kind) {
  if (this.dead) return false;
  this.endChase(false);
  this.activity = kind;
  this.paused = false;
  this.fulfill('play');
  this.requestGround(kind);
  this.emit('activity', { kind });
  return true;
}

stopActivity() {
  const kind = this.activity;
  if (!kind) return;
  this.activity = null;
  if (this.mode === 'ground' && ['jam', 'watch', 'react'].includes(this.action)) this.startGround('idle');
  this.emit('activityEnd', { kind });
}

// kind: 'scare' | 'laugh' | 'cheer'
react(kind) {
  if (this.mode !== 'ground' || !['jam', 'watch'].includes(this.action)) return;
  this.action = 'react';
  this.timer = kind === 'scare' ? 1.4 : 2;
  const clip = kind === 'scare' ? this.pickClip(['medo'], ['attacked']) : this.pickClip(kind === 'laugh' ? ['rir', 'comemorar'] : ['comemorar', 'danca'], this.emotes.length ? this.emotes : ['jump']);
  this.anim(clip, { restart: true, facing: 'front' });
  this.adjust({ mood: kind === 'scare' ? -1 : 3 });
  this.emit('react', { kind });
}

