// Ambush: run to the side of a window that covers the pet's surface and wait behind it.
planHide(s) {
  const P = this.P;
  let best = null;
  for (const w of this.world.windows.values()) {
    if (w.maximized || w.y > this.y - P * 1.1 || w.bottom < this.y - 2) continue;
