// Fun stuffs placed on the desktop floor: the pet plays with them by itself, they wear out and
// break, and clicking a broken one repairs it for half the price.
import { itemById } from './game.js';
import { DIFFICULTIES } from './behavior.js';
import { icon, cartridge } from './pixel.js';
import { GAMES } from './games.js';

const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
const rand = (a, b) => a + Math.random() * (b - a);

export class Toys {
  constructor(app, screen) {
    this.app = app;
    this.screen = screen;
    this.els = new Map();
    this.lastPlay = {};
    this.sadTimer = 30;
    this.popup = null;
    this.inspecting = null;
    const { pet, game } = app;
    pet.findToy = () => {
      const now = performance.now();
      const ids = Object.entries(game.toys)
        .filter(([id, t]) => t.placed && !t.broken && now - (this.lastPlay[id] || 0) > 45000)
        .map(([id]) => id);
      if (!ids.length) return null;
      const id = ids[Math.floor(Math.random() * ids.length)];
      return { x: this.spot(id), play: (p) => this.play(id, p) };
    };
  }

  get P() {
    return this.app.pet.P;
  }

  floorY() {
    return this.app.world.surfaces[0]?.y ?? innerHeight;
  }

  size(id) {
    return Math.round(this.P * (id === 'gameboy' ? 0.32 : id === 'bag' ? 0.3 : 0.28));
  }

  // Where the pet stands to play with a toy.
  spot(id) {
    const t = this.app.game.toys[id];
    return clamp(t.x + this.P * 0.35, this.P * 0.3, this.app.world.width - this.P * 0.3);
  }

  place(id) {
    const { pet, world, game } = this.app;
    const x = clamp((pet.x ?? world.width / 2) + pet.dir * this.P * 0.7, this.P * 0.4, world.width - this.P * 0.4);
    if (game.placeToy(id, x)) this.app.sound.play('ok', { volume: 0.4 });
  }

  play(id, pet) {
    const { game } = this.app;
    const item = itemById(id);
    const t = game.toys[id];
    if (!t || t.broken || !t.placed) return pet.chooseNext();
    this.lastPlay[id] = performance.now();
    const scale = game.difficultyScale();
    const end = (interrupted) => {
      if (id === 'gameboy') this.screen.stop();
      if (!interrupted && game.wearToy(id)) {
        this.app.sound.play('explode', { volume: 0.4 });
        pet.adjust({ mood: -6 * (DIFFICULTIES[pet.cfg.difficulty] ?? 1) });
        pet.emit('toyBroke', { item });
      }
    };
    if (id === 'gameboy') {
      this.screen.start(game.cartridge);
      pet.playToy({ id, dur: rand(14, 24), gain: item.gain, scale, hold: item.img, wobble: 0.08, onEnd: end });
    } else if (id === 'pelucia') {
      pet.playToy({ id, dur: rand(7, 11), gain: item.gain, scale, hold: item.img, wobble: 0.03, onEnd: end });
    } else {
      const clip = pet.pickClip(['comemorar', 'danca'], [...pet.emotes, 'jump']);
      pet.playToy({ id, dur: rand(6, 9), gain: item.gain, scale, anim: clip, onEnd: end });
    }
  }

  // New purchase: dropped next to the pet, which walks over, looks at it and picks it up.
  bought(item) {
    const { pet, world, game } = this.app;
    if (pet.dead || this.inspecting || pet.x === null) return;
    const x = clamp(pet.x + pet.dir * this.P * 0.9, this.P * 0.5, world.width - this.P * 0.5);
    const el = this.makeEl('toy dropped', item.img, item.icon);
    this.inspecting = { el, x, item };
    pet.inspect(x, item.img, () => {
      el.remove();
      this.inspecting = null;
      if (item.toy && !game.toys[item.id]?.placed) game.changed();
    });
  }

  makeEl(cls, src, emoji) {
    const el = document.createElement('div');
    el.className = cls;
    if (src) {
      const img = document.createElement('img');
      img.src = src;
      img.draggable = false;
      el.append(img);
    } else el.textContent = emoji || '🎁';
    document.body.appendChild(el);
    return el;
  }

  ensure(id, src) {
    let el = this.els.get(id);
    if (!el) {
      el = this.makeEl('toy', src);
      el.dataset.id = id;
      const mark = document.createElement('img');
      mark.className = 'mark';
      mark.draggable = false;
      el.append(mark);
      el.addEventListener('pointerdown', (e) => this.pointer(e, id));
      el.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (id !== 'bag') this.app.game.pickUpToy(id);
        this.app.sound.play('cancel', { volume: 0.4 });
      });
      this.els.set(id, el);
    }
    return el;
  }

  // Drag sideways to move; a click repairs a broken toy or opens the cartridge bag.
  pointer(e, id) {
    if (e.button !== 0) return;
    e.stopPropagation();
    const { game } = this.app;
    const start = e.clientX;
    const x0 = id === 'bag' ? game.bagX ?? this.bagX() : game.toys[id].x;
    let moved = false;
    const el = this.els.get(id);
    try {
      el.setPointerCapture(e.pointerId);
    } catch {}
    const move = (ev) => {
      if (Math.abs(ev.clientX - start) > 4) moved = true;
      if (!moved) return;
      const x = clamp(x0 + ev.clientX - start, this.P * 0.3, this.app.world.width - this.P * 0.3);
      if (id === 'bag') game.bagX = x;
      else game.toys[id].x = x;
    };
    const up = () => {
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', up);
      if (moved) return game.changed();
      if (id === 'bag') return this.toggleBag();
      if (game.toys[id].broken) {
        if (game.repairToy(id)) {
          this.app.sound.play('ok', { volume: 0.5 });
          this.app.pet.adjust({ mood: 5 });
          this.app.pet.emit('toyRepaired');
        } else this.app.sound.play('cancel', { volume: 0.5 });
      }
    };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
  }

  bagX() {
    const gb = this.app.game.toys.gameboy;
    return gb?.placed ? gb.x - this.P * 0.45 : this.app.world.width * 0.5;
  }

  toggleBag() {
    if (this.popup) return this.closeBag();
    const { game, sound } = this.app;
    const el = document.createElement('div');
    el.className = 'bag-popup';
    const title = document.createElement('div');
    title.className = 'title';
    title.textContent = 'Bolsa do Game Boy';
    el.append(title);
    for (const id of game.cartridges) {
      const b = document.createElement('button');
      b.className = id === game.cartridge ? 'active' : '';
      const img = document.createElement('img');
      img.src = cartridge(GAMES[id]?.color || '#888');
      b.append(img, GAMES[id]?.name || id);
      b.onclick = (e) => {
        e.stopPropagation();
        game.cartridge = id;
        game.changed();
        if (this.screen.game) this.screen.start(id);
        sound.play('ok', { volume: 0.4 });
        this.closeBag();
      };
      el.append(b);
    }
    document.body.append(el);
    this.popup = el;
    sound.play('blip', { volume: 0.5 });
    this.app.uiChanged();
  }

  closeBag() {
    this.popup?.remove();
    this.popup = null;
    this.app.uiChanged();
  }

  // Whether (x, y) is over a toy (makes the click-through overlay clickable there).
  hit(x, y) {
    for (const el of [...this.els.values(), this.popup]) {
      if (!el || el.style.display === 'none') continue;
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return true;
    }
    return false;
  }

  update(dt, hidden) {
    const { game, pet } = this.app;
    const floor = this.floorY();
    const seen = new Set();
    const list = Object.entries(game.toys).filter(([, t]) => t.placed);
    if (game.bag) list.push(['bag', { x: game.bagX ?? this.bagX(), placed: true }]);
    for (const [id, t] of list) {
      seen.add(id);
      const item = itemById(id);
      const el = this.ensure(id, id === 'bag' ? icon('bag') : item?.img);
      const size = this.size(id);
      const inHands = pet.toyPlay?.id === id && pet.toyPlay.hold;
      el.style.display = hidden || inHands ? 'none' : 'block';
      el.classList.toggle('broken', !!t.broken);
      const mark = el.querySelector('.mark');
      mark.src = t.broken ? icon('wrench') : '';
      mark.style.display = t.broken ? 'block' : 'none';
      el.title = t.broken ? `Quebrado — clique para consertar (${game.repairCost(id)} moedas)` : id === 'bag' ? 'Clique para ver os cartuchos' : 'Arraste para mover · botão direito guarda no inventário';
      let y = floor - size * (id === 'gameboy' ? 1.6 : 1);
      let x = t.x;
      if (id === 'bola' && pet.toyPlay?.id === 'bola') {
        const k = pet.toyPlay.t;
        y -= Math.abs(Math.sin(k * 5)) * this.P * 0.7;
        x = pet.x + pet.dir * this.P * 0.25 + Math.sin(k * 2.5) * this.P * 0.2;
      }
      el.style.width = `${size}px`;
      el.style.height = `${Math.round(size * (id === 'gameboy' ? 1.6 : 1))}px`;
      el.style.transform = `translate(${Math.round(x - size / 2)}px, ${Math.round(y)}px)`;
    }
    for (const [id, el] of this.els) {
      if (!seen.has(id)) {
        el.remove();
        this.els.delete(id);
      }
    }
    if (this.inspecting) {
      const s = this.P * 0.26;
      const held = pet.toyPlay?.id === 'inspect' && pet.toyPlay.t >= pet.toyPlay.holdFrom;
      const el = this.inspecting.el;
      el.style.display = hidden || held ? 'none' : 'block';
      el.style.width = el.style.height = `${s}px`;
      el.style.transform = `translate(${Math.round(this.inspecting.x - s / 2)}px, ${Math.round(floor - s)}px)`;
    }
    // A broken toy left unrepaired makes the pet sad.
    const broken = Object.values(game.toys).filter((t) => t.placed && t.broken).length;
    if (broken && !pet.dead) {
      const d = DIFFICULTIES[pet.cfg.difficulty] ?? 1;
      pet.adjust({ mood: -0.015 * d * broken * dt });
      this.sadTimer -= dt;
      if (this.sadTimer <= 0) {
        this.sadTimer = rand(40, 70);
        pet.emit('toySad');
      }
    }
  }
}

// Jam (dances to the music playing on the PC) and Assistir (watches the video behind it),
// driven by the host's audio loopback analysis: { level, bass, mid, high, beat, bpm } ~30x/s.
import { icon } from './pixel.js';

const clamp = (v, a, b) => Math.min(Math.max(v, a), b);

export class Modes {
  constructor(app) {
    this.app = app;
    this.kind = null;
    this.hue = 0;
    this.glow = 0;
    this.avg = 0.02;
    this.mids = [];
    this.scareCool = 0;
    this.laughCool = 0;
    this.laughHits = 0;
    this.noteTimer = 0;
    this.listening = false;
    window.petAPI.onAudio?.((a) => this.onAudio(a));
    app.pet.on((type, d) => {
      if (type === 'activityEnd' || type === 'death') this.stop(true);
    });
  }

  start(kind) {
    const { pet } = this.app;
    if (!pet.startActivity(kind)) return false;
    this.kind = kind;
    if (!this.listening) {
      this.listening = true;
      window.petAPI.audioListen?.(true).catch(() => {});
    }
    return true;
  }

  stop(fromPet) {
    if (!this.kind) return;
    this.kind = null;
    if (this.listening) {
      this.listening = false;
      window.petAPI.audioListen?.(false).catch(() => {});
    }
    if (!fromPet) this.app.pet.stopActivity();
  }

  onAudio(a) {
    if (!this.kind) return;
    const { pet } = this.app;
    this.avg = this.avg * 0.985 + a.level * 0.015;
    if (this.kind === 'jam') {
      if (a.bpm > 0) pet.danceSpeed = clamp(a.bpm / 115, 0.6, 1.8);
      if (pet.action === 'jam') this.app.view.animator.speed = a.level < 0.005 ? 0.35 : pet.danceSpeed;
      if (a.beat) {
        this.glow = 1;
        this.hue = (this.hue + 40 + Math.random() * 40) % 360;
        this.note(true);
        if (Math.random() < 0.04) pet.react('cheer');
      }
      return;
    }
    // Assistir: a sudden loud spike = jump-scare; a 4-7 Hz pulsing in the voice band = laughter.
    this.scareCool -= 1 / 30;
    this.laughCool -= 1 / 30;
    if (this.scareCool <= 0 && a.level > 0.12 && a.level > this.avg * 4) {
      this.scareCool = 5;
      pet.react('scare');
      return;
    }
    this.mids.push(a.mid);
    if (this.mids.length > 45) this.mids.shift();
    if (this.mids.length < 45 || this.laughCool > 0) return;
    const mean = this.mids.reduce((s, v) => s + v, 0) / 45;
    const sd = Math.sqrt(this.mids.reduce((s, v) => s + (v - mean) ** 2, 0) / 45);
    let crossings = 0;
    for (let i = 1; i < 45; i++) if ((this.mids[i - 1] - mean) * (this.mids[i] - mean) < 0) crossings++;
    const hz = crossings / 2 / 1.5;
    const laughing = mean > 0.015 && sd > mean * 0.35 && hz >= 3.5 && hz <= 8;
    this.laughHits = laughing ? this.laughHits + 1 : Math.max(0, this.laughHits - 1);
    if (this.laughHits >= 20) {
      this.laughHits = 0;
      this.laughCool = 8;
      pet.react('laugh');
    }
  }

  // A musical note floating up around the pet, colored and glowing with the beat.
  note(big) {
    const { pet, head } = this.app;
    if (!head) return;
    const el = document.createElement('div');
    el.className = 'music-note';
    const size = Math.round(pet.P * (big ? 0.16 : 0.11));
    const src = icon('note');
    el.style.width = `${size}px`;
    el.style.height = `${Math.round(size * 1.3)}px`;
    el.style.maskImage = el.style.webkitMaskImage = `url(${src})`;
    const color = `hsl(${this.hue}, 95%, 65%)`;
    el.style.background = color;
    el.style.filter = `drop-shadow(0 0 ${big ? 8 : 4}px ${color})`;
    el.style.left = `${head.x + (Math.random() - 0.5) * pet.P * 0.9}px`;
    el.style.top = `${head.y + Math.random() * pet.P * 0.3}px`;
    el.style.setProperty('--dx', `${(Math.random() - 0.5) * 40}px`);
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 1600);
  }

  update(dt) {
    if (this.kind !== 'jam') return;
    this.glow = Math.max(0, this.glow - dt * 2.5);
    this.noteTimer -= dt;
    if (this.noteTimer <= 0 && this.avg > 0.01) {
      this.noteTimer = 0.6;
      this.note(false);
    }
  }
}

