// ---------- monitors ----------
let monitors = [];
let display = config.display ?? 0;
let arrival = null;

function switchDisplay(i, how) {
  if (i === display || arrival) return;
  arrival = { display: i, ...how };
  config.display = i;
  save({ display: i });
  api.setDisplay(i).catch(() => {});
}

// Walking off the side of the screen onto the neighbouring allowed monitor.
pet.onScreenEdge = (dir) => {
  const cur = monitors[display];
  if (!cur || arrival || Math.random() < 0.5) return false;
  const j = monitors.findIndex((m, i) => i !== display && app.allowedMonitor(i)
    && Math.abs(dir > 0 ? m[0] - (cur[0] + cur[2]) : m[0] + m[2] - cur[0]) < 40
    && m[1] < cur[1] + cur[3] && m[1] + m[3] > cur[1]);
  if (j < 0) return false;
  switchDisplay(j, { edge: dir });
  return true;
};

function arrive(a) {
  if (a.atCursor && cursor) {
    pet.x = clamp(cursor.x, pet.P * 0.3, world.width - pet.P * 0.3);
    pet.y = clamp(cursor.y + pet.P * 0.8, pet.P * 1.2, world.height);
  } else if (a.edge) {
    pet.dir = a.edge;
    pet.x = a.edge > 0 ? pet.P * 0.3 : world.width - pet.P * 0.3;
    pet.y = (world.surfaces[0]?.y ?? world.height) - 1;
  } else return pet.restart();
  pet.fall(a.edge ? a.edge * pet.walkSpeed : 0, 0);
}

