button.danger:hover { background: #b23549; }
.themes { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
.theme { display: flex; align-items: center; gap: 8px; padding: 8px; border: 1px solid var(--line); background: var(--panel); color: inherit; border-radius: 8px; cursor: pointer; text-align: left; }
.theme.active { outline: 2px solid var(--accent); }
.swatch { width: 26px; height: 26px; border-radius: 6px; flex: none; border: 1px solid rgba(255,255,255,0.3); }
