.count.warn { color: #ff7b7b; }

/* ---------- desktop overlays ---------- */
.pat-hand, .bell, .held-toy, .request, .countdown, .toy, .gb-screen, .music-note { position: absolute; left: 0; top: 0; display: none; will-change: transform; }
.pat-hand, .bell, .held-toy, .countdown, .gb-screen, .music-note, .request { pointer-events: none; }
.pat-hand img, .bell img, .held-toy img, .toy img { display: block; width: 100%; height: auto; image-rendering: pixelated; }
.bell { transform-origin: 50% 0; }
.request { background: #fff; color: #222; border: 3px solid #1d1a26; border-radius: 4px; padding: 4px 8px 4px 4px; font: bold 12px/1 Consolas, monospace; box-shadow: 3px 3px 0 rgba(0,0,0,0.35); display: none; white-space: nowrap; }
.request img { width: 32px; height: 32px; image-rendering: pixelated; vertical-align: middle; margin-right: 4px; object-fit: contain; }
.request::after { content: ''; position: absolute; left: 10px; bottom: -9px; border: 6px solid transparent; border-top-color: #1d1a26; }
.countdown { font: 900 54px/1 Consolas, monospace; color: #ffd34d; text-shadow: 3px 3px 0 #1d1a26, -2px -2px 0 #1d1a26; }
.countdown.pop { animation: countPop 0.8s ease-out; }
@keyframes countPop { from { transform-origin: center; scale: 1.8; opacity: 0.2; } 30% { scale: 1; opacity: 1; } }
.toy { pointer-events: auto; cursor: pointer; }
.toy.dropped { pointer-events: none; animation: dropIn 0.4s ease-out; }
@keyframes dropIn { from { opacity: 0; margin-top: -40px; } }
.toy .mark { position: absolute; right: -6px; top: -6px; width: 16px !important; display: none; }
.toy.broken > img:first-child { filter: grayscale(0.8) brightness(0.7); }
.toy.broken { animation: brokenShake 2.5s infinite; }
@keyframes brokenShake { 0%, 90%, 100% { rotate: 0deg; } 93% { rotate: -6deg; } 97% { rotate: 6deg; } }
.gb-screen { background: #8b8b9a; padding: 6px 6px 3px; border-radius: 6px 6px 18px 6px; border: 2px solid #1d1a26; box-shadow: 3px 3px 0 rgba(0,0,0,0.35); }
.gb-screen canvas { display: block; width: 120px; height: 108px; image-rendering: pixelated; border: 3px solid #3f3f4d; }
.gb-screen div { font: bold 9px/1.4 Consolas, monospace; color: #1f1f6e; text-align: center; letter-spacing: 1px; }
.music-note { display: block; animation: noteFloat 1.6s ease-out forwards; mask-size: contain; -webkit-mask-size: contain; mask-repeat: no-repeat; -webkit-mask-repeat: no-repeat; }
@keyframes noteFloat { from { opacity: 0; transform: translate(0, 0) scale(0.6); } 15% { opacity: 1; transform: translate(0, -8px) scale(1.1); } to { opacity: 0; transform: translate(var(--dx), -70px) scale(0.9); } }
