// The ball toy as a physics object: rolls, bounces on the floor/window tops/screen edges, the
// player can grab and throw it, and the pet chases, kicks, heads and throws it.
import { icon } from './pixel.js';

const clamp = (v, a, b) => Math.min(Math.max(v, a), b);

export class Ball {
  constructor(app) {
    this.app = app;
    this.el = null;
    this.x = null;
    this.y = 0;
    this.vx = 0;
    this.vy = 0;
    this.spin = 0;
    this.held = null;
    this.bounceCool = 0;
  }

  get P() {
    return this.app.pet.P;
  }

  get r() {
    return this.P * 0.11;
  }

  get active() {
    const t = this.app.game.toys.bola;
    return !!t?.placed && !t.broken;
  }

  ensure() {
    if (this.el) return;
    const el = (this.el = document.createElement('div'));
    el.className = 'toy ball';
    el.title = 'Arraste e solte para jogar a bola · botão direito guarda no inventário';
    el.innerHTML = `<img src="${icon('ball')}" draggable="false">`;
    el.addEventListener('pointerdown', (e) => this.grab(e));
    el.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.app.game.pickUpToy('bola');
    });
    document.body.append(el);
  }

  kick(vx, vy) {
    this.vx = vx;
    this.vy = vy;
    this.bounceCool = 0;
    this.app.sound.tone8(260, 140, 0.08, 'square', 0.12);
  }

  set(x, y) {
    this.x = x;
    this.y = y;
    this.vx = this.vy = 0;
  }

  // Target for the pet's grappling hook.
  hookTarget() {
    return {
      get x() { return ball.x; },
      get y() { return ball.y; },
      move: (x, y) => this.set(x, y),
      done: () => this.kick(0, -this.P * 2),
    };
  }

  grab(e) {
    if (e.button !== 0) return;
    e.stopPropagation();
    const el = this.el;
    try {
      el.setPointerCapture(e.pointerId);
    } catch {}
    this.held = { hist: [{ t: performance.now(), x: e.clientX, y: e.clientY }] };
    this.set(e.clientX, e.clientY);
    const move = (ev) => {
      this.set(ev.clientX, ev.clientY);
      const h = this.held.hist;
      h.push({ t: performance.now(), x: ev.clientX, y: ev.clientY });
      while (h.length > 2 && h[h.length - 1].t - h[0].t > 100) h.shift();
    };
    const up = () => {
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', up);
      el.removeEventListener('pointercancel', up);
      const h = this.held.hist;
      this.held = null;
      const a = h[0];
      const b = h[h.length - 1];
      const dt = (b.t - a.t) / 1000;
      if (dt > 0.01) {
        const max = this.P * 30;
        this.vx = clamp((b.x - a.x) / dt, -max, max);
        this.vy = clamp((b.y - a.y) / dt, -max, max);
      }
      if (Math.hypot(this.vx, this.vy) > this.P * 3) this.app.pet.ballThrown();
      this.app.game.toys.bola.x = this.x;
    };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
    el.addEventListener('pointercancel', up);
  }

  hit(x, y) {
    if (!this.el || this.el.style.display === 'none') return false;
    return Math.hypot(x - this.x, y - this.y) < this.r + 6;
  }

  update(dt, hidden) {
    const { pet, world } = this.app;
    if (!this.active) {
      if (this.el) {
        this.el.remove();
        this.el = null;
      }
      pet.ball = null;
      this.x = null;
      return;
    }
    this.ensure();
    pet.ball = this;
    const r = this.r;
    const W = world.width;
    const floor = world.surfaces[0]?.y ?? innerHeight;
    if (this.x === null) this.set(this.app.game.toys.bola.x ?? W / 2, floor - r);
    if (!this.held && !(pet.hook?.target && pet.hook.phase === 'pull' && pet.hook.kind === 'pull')) {
      const g = pet.gravity;
      const y0 = this.y;
      this.vy = Math.min(this.vy + g * dt, this.P * 30);
      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.bounceCool -= dt;
      // Screen edges and top.
      if (this.x < r || this.x > W - r) {
        this.x = clamp(this.x, r, W - r);
        this.vx = -this.vx * 0.7;
      }
      if (this.y < r) {
        this.y = r;
        this.vy = Math.abs(this.vy) * 0.5;
      }
      // Floor and window tops.
      const s = this.vy >= 0 ? world.landing(this.x, y0 + r, this.y + r) : null;
      const ground = s ? s.y : this.y + r >= floor ? floor : null;
      if (ground !== null) {
        this.y = ground - r;
        if (this.vy > this.P * 1.5) {
          if (this.bounceCool <= 0) this.app.sound.tone8(180, 90, 0.05, 'triangle', Math.min(0.12, this.vy / (this.P * 120)));
          this.bounceCool = 0.08;
          this.vy = -this.vy * 0.62;
        } else {
          this.vy = 0;
          this.vx *= Math.exp(-2.2 * dt);
          if (Math.abs(this.vx) < 2) this.vx = 0;
        }
      }
      this.spin += (this.vx * dt) / r;
      this.app.game.toys.bola.x = this.x;
    }
    const s = Math.round(r * 2);
    this.el.style.display = hidden ? 'none' : 'block';
    this.el.style.width = `${s}px`;
    this.el.style.height = `${s}px`;
    this.el.style.transform = `translate(${Math.round(this.x - r)}px, ${Math.round(this.y - r)}px) rotate(${this.spin}rad)`;
  }
}

