// Thumbs mashing, swaying with the game, little jolts of excitement or frustration.
gameboyTick(dt, tp, pet) {
  if (!this.screen.game) this.screen.start(this.app.game.cartridge);
  tp.excite = Math.max(0, (tp.excite || 0) - dt * 1.4);
  tp.lean = (tp.lean ?? 0) + ((tp.leanTo ?? 0) - (tp.lean ?? 0)) * Math.min(1, dt * 3);
  tp.next = (tp.next ?? 1) - dt;
  if (tp.next <= 0) {
    tp.next = rand(0.6, 2.2);
    tp.leanTo = rand(-0.09, 0.09);
    const r = Math.random();
    if (r < 0.12) {
      tp.excite = 1;
      pet.emit('gameExcite');
      this.app.sound.tone8(660, 990, 0.12, 'square', 0.06);
    } else if (r < 0.18) {
      tp.excite = 0.6;
      tp.leanTo = -0.14 * pet.dir;
    }
  }
  const mash = Math.sin(tp.t * 15) * 0.025 + Math.sin(tp.t * 23) * 0.015;
  tp.reach = 0.26 + mash + tp.excite * 0.4;
  pet.tilt = tp.lean + Math.sin(tp.t * 1.7) * 0.03 + tp.excite * 0.1 * Math.sin(tp.t * 18);
  pet.tiltPivot = { x: 0, y: 0 };
  tp.bob = Math.sin(tp.t * 15) * 1.2;
}

// Strikes in the air: overhead cuts, side cuts, thrusts.
swordTick(dt, tp, pet) {
  tp.next = (tp.next ?? 0.3) - dt;
  tp.swing = Math.max(0, (tp.swing || 0) - dt * 2.6);
  if (tp.next <= 0) {
    tp.next = rand(0.55, 1.2);
    tp.swing = 1;
    tp.side = Math.random() < 0.5 ? -1 : 1;
    tp.kind = Math.random() < 0.3 ? 'thrust' : 'cut';
    const clip = pet.pickClip(['golpe'], ['swing_hand', 'use_mainhand', 'attacked']);
    pet.anim(clip, { facing: Math.random() < 0.6 ? 'front' : tp.side > 0 ? 'right' : 'left', restart: true });
    pet.emit('swordSwing');
    this.app.sound.swish?.();
  }
  const u = 1 - tp.swing;
  tp.angle = tp.kind === 'thrust' ? tp.side * 80 : tp.side * (-40 + 160 * Math.sin(Math.min(1, u * 1.6) * Math.PI / 2));
  tp.reach = 0.15 + tp.swing * 0.6;
  pet.tilt = tp.side * 0.12 * tp.swing;
  pet.tiltPivot = { x: 0, y: 0 };
}

