// Speech bubble typed letter by letter, voiced with 8-bit syllable blips.

const pick = (list) => list[Math.floor(Math.random() * list.length)];

// Pet event -> [lines, probability]. Lines may be functions of the event data.
const LINES = {
  bought: [['Uau! Pra mim?', 'Obrigada!', 'Que legal!'], 0.6],
  requestDone: [['Valeu!', 'Hehe, obrigada!', 'Era isso!'], 0.7],
  ballFetch: [['De novo! De novo!', 'Pega essa!', 'Iupiii!'], 0.6],
  ballHeader: [['Cabeçada!', 'Toma!'], 0.3],
  slap: [['Ai!', 'Ei! Doeu!', 'Por quê?!'], 0.8],
  patAngry: [['Chega, chega!', 'Para com isso!'], 0.8],
  pet: [['Hehe~', 'Mais!', 'Que gostoso...'], 0.2],
  wake: [['Bom dia!', 'Hmm... dormi bem.'], 0.4],
  toyBroke: [['Quebrou...', 'Ah não...'], 1],
  toyRepaired: [['Consertou! Obrigada!'], 1],
  chaseStart: [['Vou te pegar!', 'Corre, corre!'], 0.7],
  qteStart: [['Peguei!', 'Te peguei!'], 0.7],
  hookFire: [['Hookshot!', 'Lá vou eu!'], 0.25],
  supply: [(d) => [`Hora do ${d.item?.name || 'lanche'}!`, 'Peguei da mochila!'], 0.5],
  gameExcite: [['Isso!', 'Recorde!', 'Uhuul!'], 0.4],
  swordSwing: [['Hah!', 'Toma!', 'Iaaah!'], 0.12],
  leave: [['Adeus...', 'Vou embora...'], 1],
  activity: [(d) => (d.kind === 'jam' ? ['Música!', 'Vamos dançar!'] : ['O que vamos ver?', 'Pipoca!']), 0.6],
  mood: [(d) => (d.hunger < 30 ? ['Tô com fome...'] : d.thirst < 30 ? ['Que sede...'] : d.energy < 25 ? ['Tô com sono...'] : d.mood < 25 ? ['Tô triste...'] : []), 0.6],
  request: [(d) => [{ food: `Quero ${d.name || 'comida'}!`, drink: `Quero ${d.name || 'beber algo'}!`, pat: 'Faz cafuné?', play: 'Vamos brincar?' }[d.kind]], 1],
};

export class Speech {
  constructor(app) {
    this.app = app;
    this.el = document.createElement('div');
    this.el.className = 'speech';
    document.body.append(this.el);
    this.text = '';
    this.shown = 0;
    this.t = 0;
    this.cool = 0;
    app.pet.on((type, data) => this.react(type, data));
  }

  react(type, data) {
    if (this.app.config.speech === false) return;
    const entry = LINES[type];
    if (!entry) return;
    const [lines, p] = entry;
    const forced = p >= 1;
    if (!forced && (this.cool > 0 || Math.random() > p)) return;
    const list = typeof lines === 'function' ? lines(data || {}) : lines;
    if (list.length) this.say(pick(list));
  }

  say(text) {
    this.text = text;
    this.shown = 0;
    this.t = 0;
    this.life = 1.6 + text.length * 0.07;
    this.cool = this.life + 6;
    this.el.textContent = '';
  }

  update(dt, head, hidden) {
    this.cool -= dt;
    if (!this.text) {
      this.el.style.display = 'none';
      return;
    }
    this.t += dt;
    const n = Math.min(this.text.length, Math.floor(this.t * 28));
    if (n > this.shown) {
      for (let i = this.shown; i < n; i++) if (i % 2 === 0) this.app.sound.speak(this.text[i]);
      this.shown = n;
      this.el.textContent = this.text.slice(0, n);
    }
    if (this.t > this.life) {
      this.text = '';
      this.el.style.display = 'none';
      return;
    }
    this.el.style.display = hidden ? 'none' : 'block';
    const w = this.el.offsetWidth;
    const h = this.el.offsetHeight;
    const P = this.app.pet.P;
    let x = head.x - w - P * 0.2;
    if (x < 4) x = head.x + P * 0.2;
    const y = Math.max(4, head.y - h - P * 0.15);
    this.el.style.transform = `translate(${Math.round(Math.min(x, innerWidth - w - 4))}px, ${Math.round(y)}px)`;
  }
}

